-- 2026-10-01: yalnız sunucudaki sorulardan 642 tanesi düzeltilip oyunda (ya da
-- yeniden oyunda): 501 karışık dilli soru kurtarıldı, 141 soru düzeltildi.
--
-- NİÇİN: `2026-10-01_server_only_unapprove*.sql` denetlenmemiş sunucu
-- sorularını ayıkladı. İki grup çıkarılmak yerine düzeltilmeye değerdi:
--   * Kurtarma (501): Kurmancî soru + Türkçe şık yüzünden emekliye ayrılan,
--     başka kusuru gösterilmeyen sorular. Muse Spark 1.3 şıkları ve açıklamayı
--     Kurmancîye çevirdi (doğru şık ve sıra değişmedi), Grok 4.7 eski ile yeniyi
--     karşılaştırıp doğruladı (ONAY ya da küçük dil düzeltmesi).
--   * Düzeltme (141): üç oyun çoğunluğu FIX diyen (ya da ayrışıp Gemini 3.1 Pro
--     hakemliğinde DÜZELT çıkan) sorular. Gemini 3.1 Pro düzeltti, Grok 4.7
--     doğruladı.
-- Grok'un RED dediği sorular alınmadı; kurtarma adayıysa onaysız kalır,
-- onaylı bir düzeltme adayıysa (1) burada onaydan çıkarılır. Kurmancî
-- alanda alıntı dışında Türkçe harf kalan satırlar da alınmadı.
-- Mekanik denetim: doğru şık (correct_option) DEĞİŞMEZ; boş şık sayısı aynı;
-- doğru şık boş değil. Kayıt: orkestra/sunucu_denetim/ (dogrula/, sonuc/).
--
-- Yazılan alanlar: prompt, option_a..d (boş şık "-" ise sunucudaki değer
-- korunur), explanation ve explanation_ku (Kurmancî açıklama); explanation_tr
-- değişmez. Kurtarılanlar is_approved = true olur.
-- GERİ ALMA: metin değişiklikleri için önceki değerler göçten önce alınan
-- dökümde (orkestra/sunucu_denetim/yalniz_sunucu.json); onay için aynı id
-- listesiyle is_approved = false.
-- Uygulama: supabase db query --linked -f supabase/2026-10-01_server_rescue_fix.sql
begin;

create temp table _yeni(
  id uuid primary key, prompt text, a text, b text, c text, d text,
  aciklama text, kurtar boolean
) on commit drop;

do $$
declare v int;
begin
  select count(*) into v from questions q join _yeni y on y.id = q.id;
  if v <> 642 then
    raise exception 'beklenen 642 satır sunucuda, bulunan %', v;
  end if;
end
$$;

update questions q set
  prompt = y.prompt,
  option_a = coalesce(y.a, q.option_a),
  option_b = coalesce(y.b, q.option_b),
  option_c = coalesce(y.c, q.option_c),
  option_d = coalesce(y.d, q.option_d),
  explanation = coalesce(y.aciklama, q.explanation),
  explanation_ku = coalesce(y.aciklama, q.explanation_ku),
  is_approved = true,
  updated_at = now()
from _yeni y
where q.id = y.id;

update questions set is_approved = false, updated_at = now()
where id in (values
  ('05099242-25b9-4163-ac8e-9eae610ec6c8'::uuid));

do $$
declare v int;
begin
  select count(*) into v from questions q join _yeni y on y.id = q.id
  where q.is_approved and q.prompt = y.prompt;
  if v <> 642 then
    raise exception 'beklenen 642 onaylı ve güncel satır, bulunan %', v;
  end if;
end
$$;

commit;
