insert into _yeni values
  ('00be1132-62e6-4b27-a883-f9e03cd9db60'::uuid, 'Kîjan ji van peyvan Kurmancî ye ku wateya wê "yaşlı/ihtiyar" e?', 'pîr', 'mêr', 'îro', 'poz', '''yaşlı/ihtiyar'' → pîr.', false),
  ('00f9174d-ba9e-4090-bbc6-cdec192be07a'::uuid, '''Mistefa Barzanî'' bi kîjan aliyê xwe ve tê nasîn?', 'Rêberê leşkerî û siyasî yê efsanewî yê tevgera kurdî', 'Mîrektiya kurdî ya di serdema Osmanî de xweser mayî', 'Rojnameya kurdî ya destpêkê ya li Silêmaniyê hatiye çapkirin', 'Eyaleta îdarî ya demkurt a di 1847an de di dewleta Osmanî de hatiye avakirin', '''Mistefa Barzanî'': rêberê leşkerî û siyasî yê efsanewî yê tevgera kurdî.', true),
  ('011b4660-1669-4836-b0b3-74e1a34d0235'::uuid, 'Bi ''baviksalarî'' çi tê xwestin?', 'Avahiya civakî ya ku mêr serdest dike û jinê bindest dike', 'Sîstema jiyanê ya alternatîf a li hember modernîteya kapîtalîst', 'Şêweya xwerêvebirin û xwe-rêxistinkirina gel', 'Yekitiya nasnameyan bê zora dewletê', '''baviksalarî'' → avahiya civakî ya ku mêr serdest dike û jinê bindest dike.', true),
  ('01933660-ae87-4cd2-ab8c-390fe43b76a4'::uuid, 'Wêjeya nivîskî ya kurdî heta sedsala 20an bi giranî di kîjan cureyî de pêş ket?', 'Romana zanistî-xeyalî', 'Helbest', 'Senaryoya sînematîk', 'Rojnivîskên deryavaniyê', 'Iranica dibêje ku hilberîna nivîskî ya kurdî demeke dirêj bi giranî helbest bûye, nesir di sedsala 20an de pêş ketiye.', true),
  ('01b803b7-9969-49b2-8890-2b3ae384f152'::uuid, 'Di civaka kurd de xebatên dîroka devkî çima bi qîmet in?', 'Ji ber ku fêrbûna ziman asteng dike', 'Ji ber ku dîrokê bi temamî ji holê radike', 'Ji ber ku dikare ezmûn û bîrên ku di arşîvên fermî de nayên dîtin tomar bike', 'Ji ber ku tenê hejmaran dide jiberkirin', 'Dîroka devkî bi vegotinên şexsî ezmûnên wek koç, şîn, jiyana rojane û berxwedanê xuya dike.', true),
  ('01cc9ca8-e91e-4ca6-b2ca-3cd175ce9c2f'::uuid, 'Mistefa Barzanî di sala 1946an de di kîjan bûyera siyasî ya kurd de wek fermandarê leşkerî derket pêş?', 'Dewleta Eyûbiyan', 'Komara Mehabadê', 'Mîrektiya Soran', 'Peymana Civakî ya Rojava', 'Britannica diyar dike ku Mistefa Barzanî di nav artêşa Komara Mehabadê de wek fermandarekî bilind bûye.', true),
  ('02144817-d250-4ea8-8607-7d368d7cae7e'::uuid, 'Di dîrokê de ''Meryem Xan'' kî ye?', 'Hunermenda jin a kurd a yekem ku di muzîka kurdî de plak dagirtiye', 'Hunermenda gelêrî ya klasîk a populer a herêma Behdînanê', 'Şêwaza muzîka lîrîk a taybet a herêmên Qers, Agirî û Wanê', 'Dengê herî navdar ku muzîka kurdî li cîhanê daye naskirin', '''Meryem Xan'': hunermenda jin a kurd a yekem ku di muzîka kurdî de plak dagirtiye.', true),
  ('027f70f8-e269-452e-b2c4-20da03c976fa'::uuid, 'Kurdî bi şaxê hind-îranî yê kîjan malbata zimanên sereke ve girêdayî ye?', 'Ural', 'Hind-Ewropa', 'Sîno-Tîbet', 'Bantû', 'Kurdî di nav zimanên rojavayî yên îranî de di şaxê hind-îranî/îranî yên malbata zimanên hind-ewropî de tê hesibandin.', true),
  ('0313b1eb-bdb1-4977-8e3a-55949f2f1fd8'::uuid, 'Dîwana Melayê Cizîrî bi kîjan zimanî hatiye nivîsandin?', 'Erebî', 'Osmanî', 'Farisî', 'Kurmancî', 'Melayê Cizîrî dîwana xwe bi kurmancî (kurdî) nivîsiye.', true),
  ('032b96d9-af6d-4614-9ce4-2a9030f1a10c'::uuid, 'Kovara "Hawar" çima ji bo çanda kurdî girîng e?', 'Ji ber ku xebatên ziman û alfabeyê belav kir', 'Ji ber Bekoyê fitneker ê ketiye navberê', 'Ji bo nîşandana qîmeta ziman û yekitiya kurdî', 'Pêşketina cureyên wek roman û rojnameyê di serdema modern de', 'Hawar girîng e ji ber ku wê alfabeya kurdî ya latînî û xebatên zimanî yên latînî belav kir.', true),
  ('03c0215e-f593-46e9-902e-01764e80798c'::uuid, 'Kîjan amûr di govendê de rîtma bingehîn dide?', 'Erbane', 'Dahol', 'Bilûr', 'Tembûr', 'Di govendê de dahol rîtma bingehîn dide; bi gelemperî bi zirneyê re tê.', false),
  ('041054f1-81b7-48f7-959d-1bb73dc2aaa8'::uuid, 'Kurmancî bi piranî di kîjan sîstema nivîsandinê de tê nivîsandin?', 'Nivîsa bizmarî', 'Tu alfabe ji bilî alfabeya kîrîlî', 'Alfabeya Hawarê ya bi eslê xwe latînî', 'Sîstema kanaya japonî', 'Kurmancî bi alfabeya Hawarê ya latînî belav bûye, nemaze di çarçeweya Tirkiye û Sûriyê de.', true),
  ('05360e6b-f052-4872-91b5-677bfe66854d'::uuid, 'Derbarê ''Munzur dağları'' de ya rast kîjan e?', 'Rêzeçiyayên herî asê yên cografyaya Dêrsimê', 'Çiyayê stratejîk ê di nav deşta Mûsilê de bilind dibe', 'Geliyê kanyonî yê kûr ê ku Çemê Botanê çêkiriye', 'Deyşta mezin a çandiniyê ya ku şaxên Firatê av didinê', '''Munzur dağları'' → Rêzeçiyayên herî asê yên cografyaya Dêrsimê.', true),
  ('05b274cd-3346-420d-9e9f-e94602a0a854'::uuid, '''Kardeş Türküler'' kî ne?', 'Hunermendê gelêrî yê klasîk ê populer ê herêma Behdînanê', 'Dengbêjê ku hestên neteweyî yên gelê kurd tîne ziman', 'Hunermendê ku di serdema modern de muzîka gelêrî ya kurd pêşkêş dike', 'Koma ku muzîka kurdî di hawîrdoreke pirçandî de pêşkêş dike', '''Kardeş Türküler'': koma ku muzîka kurdî di hawîrdoreke pirçandî de pêşkêş dike.', true),
  ('05c3350b-9ccb-48fe-ba60-e71a9261aede'::uuid, 'Di dîroknivîsîna kurdî de berhema bi navê Şerefname bi kê ve tê girêdan?', 'Şeref Xanê Bedlîsî', 'Ehmedê Xanî', 'Cegerxwîn', 'Miqdad Midhet Bedirxan', 'Şerefname yek ji çavkaniyên destpêkê yên girîng e derbarê mîrgeh û xanedanên kurd de.', true),
  ('05ca14a1-d827-4a1d-9b34-facf53c44635'::uuid, 'Piştî 1991ê li bakurê Iraqê ji bo kurdan kîjan pêvajo xurt bû?', 'Rêveberiya xweser a de facto û paşê sazîbûna KRGê', 'Rêveberiya kolonyal a tevahî', 'Statuya parêzgeha Romayê', 'Rêveberiya xanedaniya Moxolan', 'Piştî 1991ê li Kurdistana Iraqê pêşketina saziyên rêveberiya xweser yek ji pêvajoyên dîrokî yên bingehîn ên KRGê ye.', true),
  ('05cfeb04-09fa-4987-b4b7-59c774765f4a'::uuid, '"Kerkûk" li kîjan welatî ye?', 'Sûriye', 'Iraq', 'Tirkiye', 'Îran', 'Kerkûk bajarekî Iraqê ye ku bi statuya xwe ya dîrokî ya pirçandî û nakokbar tê naskirin.', true),
  ('066045ef-b32a-4fa4-b437-271263675981'::uuid, 'Çima xalîçe û tekstîlên kurdî di xebatên çandî de girîng in?', 'Ji ber ku tu motîf tê de nînin', 'Ji ber ku tenê ji plastîk têne çêkirin', 'Ji ber ku zanîna jiyana rojane, motîf û estetîka herêmî hildigirin', 'Ji ber ku tenê kodên nermalavê ne', 'Tevn û motîfan der barê bîra herêmî, hilberîn û cîhana estetîk a civakan de îşaretan digirin.', true),
  ('067ebbda-692a-4a9e-924d-260d50831919'::uuid, 'Sîstema hevserokatiyê armanc dike kîjan prensîbî sazî bike?', 'Nûnertiya wekhev a jinan û mêran û rêveberiya hevbeş', 'Rêveberiya bêsînor a kesekî tenê', 'Tenê qezenca aborî', 'Qedexeya ziman', 'Hevserokatî modelek e ku ji bo nûnertiya siyasî ya jinan û rêveberiya hevbeş di pêvajoyên biryargirtinê de qad vedike.', true),
  ('06c9bba7-73e0-4553-9d00-6d762dc2a0b2'::uuid, '"Teyran" di paşnavê "Feqiyê Teyran" de bi çi re têkildar e?', 'Axaftina dualî', 'Çûk (teyr = çûk)', 'Celadet Alî Bedirxan', 'Evîna Mem û Zînê', '"Teyran" bi çûkan (teyr = çûk) ve girêdayî ye; ev eleqeya helbestvan bi xwezayê û motîfên çûkan re nîşan dide.', true),
  ('07308d3d-166c-4e73-b41d-45264427defc'::uuid, 'Herêma "Dêrsim" bi piranî bi kîjan kevneşopî re têkildar e?', 'Qralekî/tîranekî zalim', 'Şeref Xanê Bedlîsî', 'Elewîtî (Qizilbaş)', 'Şerefxanê Bedlîsî', 'Herêma Dêrsimê (Tuncelî) bi giranî bi kevneşopiya baweriya Elewî-Qizilbaş ve girêdayî ye.', true),
  ('07777350-a56a-477f-aaee-351d6da9187f'::uuid, 'Di çanda Kurdî de Newroz herî zêde bi kîjan qadê re têkildar e?', 'Govenda komî ya bi şêweya xelekê', 'Hatina biharê û nûbûn', 'Xurtkirina girêdanên civakî', 'Gotina kilam an vegotinê bi dorê', 'Newroz di çanda Kurdan de di çarçoveya 21ê Adarê de tê nirxandin.', true),
  ('077b93af-a29b-47b5-be1a-c8a3b6ca0b77'::uuid, 'Kê yek ji yekem mewlûdên nivîskî yên zazakî (kirmanckî) nivîsandiye?', 'Mela Ehmedê Xasî', 'Melayê Cizîrî', 'Ehmedê Xanî', 'Mehmed Uzun', 'Mela Ehmedê Xasî, bi nivîsandina yek ji yekem mewlûdên nivîskî yên zazakî (kirmanckî) tê naskirin.', false),
  ('0799cfb5-d05b-45bb-a8be-67c7ffa594d0'::uuid, 'Kîjan herêm bi tevgera "Şêx Ubeydullah" (1880) re têkildar e?', 'Trakya', 'Derdorên Colemêrg/Şemdînanê', 'Behra Reş', 'Ege', 'Tevgera Şêx Ubeydullah (1880) tevgereke kurd e ku li derdora Colemêrg-Şemdînanê derketiye holê.', true),
  ('07f3abfe-b267-4137-9596-7f17362e8d84'::uuid, 'Ji bilî kurdan kîjan gelên din Newrozê pîroz dikin?', 'Govend tê kişandin û li ser agir tê bazdan', 'Cilên dirêj ên rengîn û qatqat (kiras)', 'Îranî û gelek gelên din (wek Nevruz)', 'Veguhestina êş, windahî û bîra civakî', 'Cejna Newrozê ji aliyê Kurd, Îranî û gelek gelên herêmê ve tê pîrozkirin.', true),
  ('08144c7d-9c17-4abc-bb10-0ca1876a944f'::uuid, 'Atolyeya bi navê The Factory ya kîjan hunermendî bû?', 'Pablo Picasso', 'Salvador Dalí', 'Henri Matisse', 'Andy Warhol', 'The Factory navê studyoya Andy Warhol bû ku hunermend û hilberînerên cuda li wir kom dibûn.', false),
  ('084132e0-3540-4dbc-a499-c7f412054715'::uuid, 'Di civaka Kurd de pêkhateyên eşîrî di dîrokê de xwedî kîjan fonksiyon in?', 'Tenê dekora şanoyê', 'Rêxistina civakî, ewlehî, hilberîn û tora pêwendiyên siyasî', 'Tu fonksiyona civakî nîne', 'Fîloya deryayî', 'Avahiyên eşîrî di dîrokê de parçeyek ji torên hevgirtina civakî û desthilatdariya siyasî ne.', true),
  ('085b0c78-c05a-49ab-acad-83c0ea8041ff'::uuid, 'Gola Urmiyê (Urmiye) li kîjan welatî ye?', 'Iraq', 'Tirkiye', 'Îran', 'Azerbeycan', 'Gola Urmiyê goleke mezin e li bakurê rojavayê Îranê û nêzîkî herêma kurdan e.', true),
  ('088f0730-2165-44ea-8b6f-d4000da137b8'::uuid, 'Ji kesê ku govendê dikişîne re çi tê gotin?', 'Çîrokbêj', 'Dengbêj', 'Sergovend', 'Mîr', 'Ji kesê ku îdare û serê govendê dike re sergovend tê gotin.', false),
  ('08a35dd3-26e8-49fe-ad71-34cf101ba7df'::uuid, 'Bilûr amûreke pifkirinê ye.', 'Rast', 'Şaş', null, null, 'Bilûr bi pifkirinê tê lêxistin.', false),
  ('0905640a-2f54-4a39-9203-676b51830805'::uuid, '''Nûbihara Biçûkan'' çi ye?', 'Dîwana helbestan a navdar ku evîna mîstîk û felsefeyê dihewîne', 'Ferhenga kurdî ya yekem a ji aliyê Ehmedê Xanî ve hatiye nivîsandin', 'Romannivîsê hosta yê bi eslê xwe kurd ê li cîhanê tê naskirin', 'Ji ber ku xebatên ziman û alfabeyê belav kir', '''Nûbihara Biçûkan'' → ferhenga kurdî ya yekem a ji aliyê Ehmedê Xanî ve hatiye nivîsandin.', true),
  ('0958f003-43f9-4e56-ad94-b7ce2ed408eb'::uuid, 'Cigerxwîn berhemên xwe bi kîjan zimanî nivîsîne?', 'Fransî', 'Kurdî (kurmancî)', 'Rusî', 'Îngilîzî', 'Cigerxwîn berhemên xwe bi kurdî (kurmancî) nivîsîne.', true),
  ('095e11aa-879c-4f36-881c-aad17b49c697'::uuid, '''Behdînan bölgesi'' di erdnîgariyê de çi îfade dike?', 'Çiyayê dîrokî ku tê bawerkirin keştiya Nûh lê danişiye', 'Platoya kevirî ya ji lavên Qerecdaxê çêbûyî', 'Rêzeçiyayên herî asê yên cografyaya Dêrsimê', 'Herêma cografî ya çiyayî li dora Zaxo û Dihokê', '''Behdînan bölgesi'' → Herêma cografî ya çiyayî li dora Zaxo û Dihokê.', true),
  ('0a6d85fa-b27f-439b-ac9f-98da17c3ee02'::uuid, 'Newroz bi kîjan efsaneyê tê girêdan?', 'Tofanê Nûh', 'Romulus û Remus', 'Şerê Troyayê', 'Kawayê hesinkar û Dehaqê zalim', 'Newroz bi efsaneya serhildana Kawayê hesinkar a li dijî Dehaqê zalim ve girêdayî ye.', true),
  ('0ae38abc-5135-471d-a698-9356fb36c53a'::uuid, 'Derbarê ''Nemrut krateri'' de ya rast kîjan e?', 'Deşta tektonîk a bilind a li Colemêrgê', 'Çiyayê xwedî gola kraterê ya herî mezin a duyemîn a cîhanê', 'Gola bendavê ya çêkirî ya li nêzî Silêmaniyê', 'Çiyayê stratejîk ê di nav deşta Mûsilê de bilind dibe', '''Nemrut krateri'' → Çiyayê xwedî gola kraterê ya herî mezin a duyemîn a cîhanê.', true),
  ('0c51e40d-4f68-4c7f-a517-f1f1cbbb321d'::uuid, '"Hesenweyhî" xanedaneke kurd e, li kîjan herêmê hukum kiriye?', 'Qefqasya (derdora Gence-Aniyê)', 'Şeref Xan (mîrê Bedlîsê)', 'Rojavayê Îranê / derdorên Zagrosê', 'Tevgera neteweyî ya kurdên Iraqê', 'Hesenweyhî di Serdema Navîn de li derdorên Rojavayê Îranê û Zagrosê hukum kiriye, xanedaneke kurd e.', true),
  ('0d90498b-8330-498a-9813-b792f9acec53'::uuid, 'Li jêr ji bo ''Van gölü'' kîjan rast e?', 'Girseya çiyayî ya li nêzî Çemê Garzanê', 'Gola tektonîk a li ser sînorê Xarpêtê', 'Hewzeya ku gola soda ya herî mezin a cîhanê ye', 'Çemê mezin ê ku jiyanê dide Mezopotamyayê', '''Van gölü'' → Hewzeya ku gola soda ya herî mezin a cîhanê ye.', true),
  ('0e80c6a2-204d-4f38-ad35-345bf3f2b11e'::uuid, 'Di Êzîdîtiyê de kevneşopiya duakirina ber bi rojê çi nîşan dide?', 'Pîroziya ku ji ronahiyê/rojê re tê dayîn', 'Melekê Tawûs û motîfa ronahiyê/rojê', 'Bi çanda rojane re têkildar e', 'Xurtkirina girêdanên civakî', 'Di kevneşopiya Êzîdî de pîroziya ku ji rojê/ronahiyê re tê dayîn, di şêweyên îbadetê de jî xuya dike.', true),
  ('0ed1cd8c-49b4-481d-b7ba-c795d3de200d'::uuid, 'Di pêjgeha kurdî de dolme/yaprax bi giştî çi ye?', 'Amûreke muzîkê', 'Tenê şerbeta şîrîn', 'Hûrê nanê hişk', 'Xwarina sebzeyan an pelan ên ku bi têkela birincî hatine dagirtin', 'Di pêjgeha kurdî de dolme an yaprax bi dagirtina pelan û sebzeyan bi têkela birinc û goşt tê çêkirin.', true),
  ('0f581c69-8227-4541-a6a7-444506592187'::uuid, '''Gola Hazarê'' li ku ye?', 'Rêzeçiyayên herî asê yên erdnîgariya Dêrsimê', 'Çemê ku di bin sûra Amedê re derbas dibe', 'Gola tektonîk a li nav sînorên Elezîzê', 'Gola bendavê ya li ser çemê Diyalayê hatiye avakirin', '''Gola Hazarê'' → gola tektonîk a li nav sînorên Elezîzê.', true),
  ('0fa9ea42-b5f9-403a-b7fd-a6c722b7ad16'::uuid, 'Teorîya Big Bang yekem car ji aliyê kîjan kesayetiyê ve hate pêşniyarkirin?', 'Galileo Galilei', 'Charles Darwin', 'Georges Lemaître', 'Isaac Newton', 'Georges Lemaître, fizikzan û keşîşê katolîk, di pêşxistina fikirê Big Bang de roleke bingehîn hebû.', false),
  ('0fd6dda8-8c96-4fe4-b464-8b736caebf09'::uuid, 'Gotina Başûr di navlêkirina herêmî ya kurdî de bi piranî behsa çi dike?', 'Cihê niştecihbûnê yê girê dîrokî yê mîrateya UNESCOyê', 'Başûrê Kurdistanê / Kurdistana Iraqê', 'Hem parêzgeha Agiriyê hem Çiyayê Agiriyê', 'Herêma Botan/Cizîrê (başûrrojhilat)', 'Başûr tê wateya "başûr" û di bikaranîna hevpar a siyasî-çandî de, behsa Kurdistana Iraqê dike.', true),
  ('0fedd19c-e173-49b7-b944-bb6ceafc9b12'::uuid, 'Govend di bingehê de çi cure bûyer e?', 'Xwendina helbestê', 'Strana takekesî', 'Pêşandana şanoyê', 'Reqasa gelêrî ya bi kom', 'Govend reqaseke gelêrî ya kolektîf e ku bi destên hev girtî tê kirin.', true),
  ('10d1fbf2-0b76-4364-a522-3982c55430ac'::uuid, 'Selaheddîn wekî damezrînerê kîjan xanedanê tê zanîn?', 'Xanedana Sefewiyan', 'Xanedana Eyûbiyan', 'Xanedana Osmaniyan', 'Xanedana Ebasiyan', 'Britannica Selaheddîn wekî damezrînerê xanedana Eyûbî û hukumdarekî ku li Misir-Sûriyê ye bi nav dike.', true),
  ('10d25e12-66d2-4736-9ab9-9596d10cda52'::uuid, 'Helbestvanên kurd ên klasîk berhemên xwe di nav kîjan kevneşopiyê de nivîsîne?', 'Di nav rojnamegeriya modern de', 'Di nav kevneşopiya dîwan û medreseyan de', 'Di nav şanoyê de', 'Di nav sînemayê de', 'Helbestvanên kurd ên klasîk bi giranî di nava kevneşopiya dîwan û medreseyan de berhem çêkirine.', true),
  ('10ea33a4-6113-42c8-83cb-f44a839cbe67'::uuid, 'Şeref Xan, nivîskarê "Şerefnameyê", di kîjan sedsalê de jiyaye?', 'Sedsala 13an', 'Sedsala 20î', 'Sedsala 16an', 'Sedsala 18an', 'Şeref Xan di sedsala 16an de jiyaye û di sala 1597an de Şerefname nivîsiye.', true),
  ('11310887-111b-4d71-a98d-5e40703aac30'::uuid, 'Celal Talebanî gihîşt kîjan meqamê?', 'Qralê Misrê', 'Serokwezîrê Sûriyê', 'Serokkomarê Iraqê', 'Şahê Îranê', 'Celal Talebanî di sala 2005an de bû serokkomarê Iraqê.', true),
  ('11a7ccf0-0afa-49ad-a677-aa02aa6dec0f'::uuid, 'Newroz bi gelemperî bi kîjan dîrokê tê girêdan?', '1ê Kanûna Paşîn', '21ê Adarê', '30ê Tebaxê', '29ê Cotmehê', 'Di asta UNESCO û NYê de Newroz bi 21ê Adarê û ekînoksa biharê ve tê girêdan.', true),
