  ('21bf615e-9ac2-424f-8b75-30064fa4bd94'::uuid, 'Vexwarina cureya dew bi kîjan hêmana sereke ve girêdayî ye?', 'Lîkora qehweyê', 'Mast/dew', 'Tenê qalikê lîmonê', 'Ardê misirê', 'Dew bi kevneşopiya vexwarina mastê teze ve girêdayî ye.', true),
  ('21c76498-fbc0-41f4-b943-c936689fa3dd'::uuid, 'Di wêjeyê de derbarê ''Erebê Şemo'' de vebijarka rast kîjan e?', 'Vegotina devkî û veguhestina çîrokên bi awaz', 'Rojnameya kurdî ya ku bi salan li Êrîvanê hatiye weşandin', 'Helbestvanê dîwanê yê klasîk ê helbesta tesewufî ya kurdî', 'Nivîskarê yekem romana kurdî ya bi navê Şivanê Kurd', '''Erebê Şemo'' nivîskarê yekem romana kurdî ya bi navê Şivanê Kurd e.', true),
  ('21cb4e7c-af55-429e-b260-88bd1d84bf32'::uuid, 'Xanedana Eyûbiyan di kîjan serdemê de li Rojhilata Navîn bi bandor bû?', 'Sedsalên 5-6an', 'Sedsalên 12-13an', 'Sedsalên 18-19an', 'Dawiya sedsala 20an', 'Eyûbî di dawiya sedsala 12an û destpêka sedsala 13an de li Misir, Sûriye û herêmên derdorê desthilatdar bûn.', true),
  ('2226270d-607d-4396-9ec5-380143fe63d6'::uuid, 'Derbarê ''demokrasiya rasterast'' de agahiya herî rast kîjan e?', 'Têkiliya di navbera zordestiyê û wêrankirina xwezayê de', 'Beşdarbûna civaka herêmî di pêvajoyên biryargirtina xwe de', 'Sêgoşeya endustriyalîzm, dewlet-netew û kapîtalîzmê', 'Girtina biryaran rasterast ji aliyê gel ve bê nûner', '''Demokrasiya rasterast'' biryargirtina rasterast a gel e bê nûner.', true),
  ('2254f332-c0ef-4549-be96-98b1d8e4f91b'::uuid, 'Qesra Îshak Paşa nêzîkî kîjan bajarî ye?', 'Amed', 'Bazîd', 'Mêrdîn', 'Colemêrg', 'Qesra Îshak Paşa li nêzîkî Bazîdê ye.', false),
  ('226d4a9e-a568-4211-983a-5413862702b0'::uuid, 'Êzidîtî bi kevneşopî yek ji baweriyên kîjan civakê ye?', 'Ereb', 'Suryanî', 'Tirkmen', 'Kurd', 'Êzidîtî baweriya kevneşopî ya civaka êzidî ya kurdîaxêv e.', true),
