  ('2bbf8d92-6f57-444e-a0f0-b61b849fac49'::uuid, 'Di dîrokê de axên di navbera Dîcle û Firatê de çi ne?', 'Çol', 'Deşt', 'Hîlala Berhemdar / Mezopotamya', 'Tundra', 'Herêma di navbera Dîcle û Firatê de herêmeke bi bereket e ku jê re Hîlala Berhemdar / Mezopotamya tê gotin.', true),
  ('2bc57582-414d-4144-bf97-c1345021bfee'::uuid, 'Di efsaneya Newrozê de Dehak wekî kesekî çawa tê vegotin?', 'Leşkerekî qehreman', 'Hakimekî zana', 'Keyekî zalim / zordar', 'Bazirganekî comerd', 'Di vegotina Newrozê de Dehak wekî keyekî/zordarekî zalim ê ku zilmê li gel dike tê teswîrkirin.', true),
  ('2bc5bc29-0064-4063-a6f0-844f70caf8d0'::uuid, 'Navê yekem rojnameya kurdî çi ye?', 'Hawar', 'Kurdistan', 'Azadiya Welat', 'Rojnameya Nû', 'Rojnameya Kurdistanê di dîroka çapemeniyê de wek yekem rojnameya kurdî xwedî cihekî taybet e.', true),
  ('2c5efdc7-3ffb-4074-879f-7bf5245026e6'::uuid, 'Gotina ''Bakur'' di navlêkirina herêmî ya kurdî de ji bo kîjan herêmê tê bikaranîn?', 'Herêma kurdî ya li Îranê', 'Herêma kurdî ya li Tirkiyeyê', 'Herêma kurdî ya li Sûriyeyê', 'Diyasporaya kurdî ya li Lubnanê', 'Bakur ji bo erdnîgariya kurdî ya li Tirkiyeyê navekî berbelav e.', true),
  ('2c627f4b-72d9-43cb-8a63-91f76f77b885'::uuid, '''Qazî Mihemed'' kî ye?', 'Belge an tiştê ji serdemê mayî (çavkaniya seretayî)', 'Serokkomarê Komara Kurdî ya Mehabadê', 'Xanedana kurdî ya serdema navîn a navenda Amedê', 'Rêberê bihêz ê bi leqeba kor ê mîrektiya Soran', '''Qazî Mihemed'' serokkomarê Komara Kurdî ya Mehabadê ye.', true),
  ('2c792944-def7-4bdd-9ab2-cdb88821318c'::uuid, 'Şivan Perwer bi kîjan nasnameyê tê naskirin?', 'Dîroknas', 'Helbestvanê serdema klasîk', 'Wênesaz', 'Dengê navdar ê muzîka kurdî', 'Şivan Perwer yek ji dengên navdar ên muzîka kurdî ye.', true),
  ('2ca81b9a-63ce-44f6-a7a9-32dee5e207ab'::uuid, '''Eyşe Şan'' di kîjan qadê de navekî naskirî ye?', 'Dengbêja jin a navdar a kurd', 'Nivîskar', 'Wênesaz', 'Mîmar', 'Eyşe Şan (Ayşe Şan) yek ji dengbêjên jin ên navdar ên muzîka kurdî ye.', true),
  ('2cbd128a-bcaa-4c8f-a33b-ced67d2f9520'::uuid, 'Kîjan gotin ''Geliyê Munzurê'' rast tarîf dike?', 'Çiyayê volkanî yê vemirî yê li bakurê Gola Wanê', 'Çemê girîng ê ku ji Êlihê derbas dibe û diherike Dîcleyê', 'Geliyê li Dêrsimê yê di statuya parka neteweyî de', 'Deşta çandiniyê ya mezin a ku şaxên Firatê av didinê', '''Geliyê Munzurê'' geliyê li Dêrsimê ye yê di statuya parka neteweyî de.', true),
  ('2cbe2b93-2d06-4dd5-9f55-ce12ae977b31'::uuid, 'Govend, dengbêjî û kilam bi hev re çi pêk tînin?', 'Kevneşopiya cazê', 'Muzîka klasîk a rojavayî', 'Pîşesaziya pop a nûjen', 'Mîrateya muzîk-çandî ya kurdî', 'Govend, dengbêjî û kilam bi hev re mîrateyeke kurdî ya muzîkî-çandî ya dewlemend pêk tînin.', true),
  ('2cf6bc64-3ba4-4163-be3d-96b2fa596976'::uuid, 'Çima cihêrengiya xwarinên herêmî di pêjgeha kurdî de bi yek rîsipeke standard nayê kêmkirin?', 'Ji ber ku herêm, zarava, avhewa, çandinî û têkiliya bi pêjgehên cîran re cuda ne', 'Tora rêxistina civakî, ewlehî, hilberîn û têkiliyên siyasî', 'Li kêleka piraniya misilman civakên baweriyê yên êzidî, elewî, yarsanî / Ehlê Heq û yên din jî hene', 'Ji ber ku dikare ezmûn û bîra ku di arşîvên fermî de nayên dîtin tomar bike', 'Ji ber ku erdnîgariya kurdan fireh e, dibe ku li gor herêman navên malzemeyan û reçeteyan cuda bin.', true),
  ('2d763f17-a7eb-4d24-b457-96b6f17e6408'::uuid, 'Di edebiyata kurdî ya nûjen de çima mijara sirgûn / diyasporayê derdikeve pêş?', 'Wek berhemeke neteweyî / klasîk', 'Ji ber ku gelek nivîskar li derveyî welat berhem didin', 'Bi weşana yekem rojnameya kurdî Kurdistanê ve girêdayî ye', 'Xebatên rêzimanê yên kurdî (kurmancî)', 'Rastiya ku gelek nivîskarên kurd li derveyî welat berheman didin, mijara sirgûn û diyasporayê radixe ber çavan.', true),
  ('2d8cbd96-cc3a-4eae-8664-a95947302e44'::uuid, 'Edebiyata kurdî ya nivîskî heta sedsala 20an di kîjan cureyê de pêşketiye?', 'Rojnivîskên deryavaniyê', 'Romana zanistî-xeyalî', 'Senaryoya sînematîk', 'Helbest', 'Berhema kurdî ya nivîskî demeke dirêj bi giranî helbest bû û di sedsala 20an de pexşan pêş ket.', true),
  ('2dff9111-1a40-4257-b25b-e65ab3525c43'::uuid, 'Ji bo ''Cizre'' pênaseya derbasdar kîjan e?', 'Çalaka jin a kurd a ji aliyê rejîma Iraqê ve hatiye bidarvekirin', 'Navê dîrokî yê Amedê di serdema antîk de û keleha wê', 'Bajarê ku dergûşa mîrnişîna Botanê û çanda dîrokî ye', 'Berxwedana li dora Çiyayê Agiriyê di salên 1927-1930an de', '''Cizre'' → Bajarê ku dergûşa mîrnişîna Botanê û çanda dîrokî ye.', true),
  ('2e6b6423-46e6-48a0-a282-9294124bfd59'::uuid, 'Bajarê ''Efrîn'' li kîjan welatî ye?', 'Tirkiye', 'Sûriye', 'Îran', 'Iraq', 'Efrîn wargeheke kurdan e li bakurê rojavayê Sûriyeyê.', true),
  ('2ebc9e75-a597-40ef-9783-e41d6e4e07ab'::uuid, 'Li jêr ji bo ''hişmendiya ekolojîk'' ya rast kîjan e?', 'Jiyana hevpar a wekhev a ne li ser zext û xwedîderketinê', 'Têgihîştina ku mirov parçeyekî xwezayê ye', 'Nedîtina xwezayê tenê wek tiştê kedxwariyê', 'Yekitiya pirçandî û wekhevîxwaz a li welatê hevpar', '''Hişmendiya ekolojîk'' têgihîştina ku mirov parçeyekî xwezayê ye.', true),
  ('2ec02596-8a2b-472c-82fc-65e3aa478bcc'::uuid, 'Derbarê ''danûstandinê'' de kîjan rast e?', 'Meclîsên gel ên ku biryarên herêmî lê tên girtin', 'Rêbaza çareserkirina pirsgirêkan bi rêya diyalogê', 'Parastina mafan bi qanûnê', 'Beşdarbûna rasterast a gel di biryarên siyasî de', '''Danûstandin'' rêbaza çareserkirina pirsgirêkan bi rêya diyalogê ye.', true),
  ('2ec280f7-44bd-48d2-bd33-e6729e8d8316'::uuid, 'Çima Peymana Sevrê ya 1920an di warê pirsgirêka kurd de gelek caran tê gotin?', 'Ji ber ku Mehabad ava kiriye', 'Ji ber ku kurdî qedexe kiriye', 'Ji ber ku Keleha Hewlêrê xistiye UNESCOyê', 'Ji ber ku madeyên xweseriyê / serxwebûna muhtemel ji bo kurdan hatine nîqaşkirin', 'Sevr di nîqaşên siyasî yên nûjen ên kurdan de ji bo nîqaşên xweseriyê û statuya muhtemel tê binavkirin.', true),
  ('2ed3fe61-1f92-490d-a93d-fff99c8f516d'::uuid, 'Êzidî di erdnîgariya çandî ya kurdî de bi taybetî bi kîjan sernavî têne bibîranîn?', 'Veguhestina êş, windahî û bîra civakî', 'Civaka olî-çandî ya resen û travmayên dîrokî', 'Îranî û gelek gel (wek Newroz)', 'Tora rêxistina civakî, ewlehî, hilberîn û têkiliyên siyasî', 'Êzidî di nav civakên kurdaxêv de bi avahiya baweriya resen û travmayên dema dawî ve derdikevin pêş.', true),
  ('2edc356f-4536-45e7-a7e2-483d08c97534'::uuid, '''Komara Mehabadê'' bi çi awayî girîngiyeke sembolîk heye?', 'Rêveberiya xweser a de facto û paşê sazîbûna Hikûmeta Herêma Kurdistanê', 'Bi yek ji yekem ezmûnên dewleta kurdî ya nûjen bûna wê', 'Lêkolîna rabirdûyê bi bermahiyên madî', 'Dîroka xanedan û mîrektiyên kurdî', 'Komara Mehabadê (1946) wek yek ji yekem ezmûnên dewleta kurdî ya nûjen xwedî girîngiyeke sembolîk e.', true),
  ('2f48d98a-5192-48a2-9938-5f0bb2d80a95'::uuid, 'Ji aliyê wêjeyê ve ji bo ''rojnameya Riya Teze'' gotina rast kîjan e?', 'Rojnameya kurdî ya ku bi salan li Êrîvanê hatiye çapkirin', 'Helbestvan û zanayê olî yê ku yekem mewlûda zazakî nivîsiye', 'Helbestvana navdar a jin a ku di mîrektiya Erdelanê de jiyaye', 'Helbestvanê mezin ê ku şêwaza azad aniye helbesta kurdî', '''Rojnameya Riya Teze'' rojnameya kurdî ye ku bi salan li Êrîvanê hatiye çapkirin.', true),
