  ('63d84677-4ca0-450c-a10c-91b50cfe4984'::uuid, 'Kîjan têgeha “avhewaya deryaya spî” di nav erdnîgariyê de rast bi cih dike?', 'Çemê girîng ê ku ji Batmanê derbas dibe û diherike Dîcleyê', 'Platoya kevirî ya ku lavên Qerecdaxê çêkirine', 'Avhewaya ku li herêmên kurdan ên nêzî Deryaya Spî tê dîtin', 'Deşta berhemdar a ku deştên Cizîr û Silopiyê digire nav xwe', '“avhewaya deryaya spî” → avhewaya ku li herêmên kurdan ên nêzî Deryaya Spî tê dîtin.', true),
  ('640c807c-421f-4c67-9f72-a77405df6a42'::uuid, 'Di warê erdnîgariyê de “Geliyê Zapê” çi îfade dike?', 'Beşa bilind a bakur-rojava ya erdnîgariya Kurdistanê', 'Çiyayê stratejîk ê ku di nav deşta Mûsilê de bilind dibe', 'Geliyê kûr ê ku ava Zapê di nav zinaran de diherike', 'Deşta berhemdar a ku deştên Cizîr û Silopiyê digire nav xwe', '“Geliyê Zapê” → geliyê kûr ê ku ava Zapê di nav zinaran de diherike.', true),
  ('64aa54d5-093d-4fad-8c06-82a623b9f364'::uuid, 'Kurdiya soranî li Iraq û Îranê bi piranî bi kîjan sîstema nivîsandinê tê nivîsandin?', 'Nivîsa runîk', 'Ji bilî alfabeya latînî ya Hawarê qet nayê nivîsandin', 'Alfabeya kurdî ya bingeh-erebî', 'Alfabeya gurcî', 'Soranî li Iraq û Îranê bi berfirehî bi alfabeya kurdî ya bingeh-erebî tê nivîsandin.', true),
  ('64b76781-b54a-40b9-a669-b6e4fa7ad5b9'::uuid, '"Mem û Zîn" îro di edebiyata kurdî de çawa cih girtiye?', 'Wekî şahesereke neteweyî/klasîk', 'Wekî pirtûkeke dersê ya asayî', 'Wekî çîrokeke zarokan', 'Wekî metneke jibîrkirî', 'Mem û Zîn wekî şahesera neteweyî/klasîk a edebiyata kurdî tê binavkirin.', true),
  ('6575a0a0-0193-4d8d-afb5-373d73a95e3b'::uuid, 'Derbarê "Qerecdax"ê de agahiya herî rast kîjan e?', 'Çemê girîng ê ku ji Batmanê derbas dibe û dirije Dîcleyê', 'Deşta berhemdar a ku deştên Cizîr û Silopiyê digire nava xwe', 'Volkanê bazaltî yê fireh ê ku li deşta Amedê ye', 'Nebat û dara tîpîk a çiyayên Kurdistanê', '"Qerecdax" volkanê bazaltî yê fireh ê li deşta Amedê ye.', true),
  ('6591066f-5db0-4840-b2e0-5a000718c99f'::uuid, 'Ji aliyê dîrokê ve ji bo "Rojnameya Jiyan" îfadeya rast kîjan e?', 'Komkujiya rejîma Iraqê ya li dijî kurdan', 'Helbestvanê ku di sedsala 17an de fikra ronakbîriya kurdî nivîsiye', 'Êrîşa kîmyewî ya sala 1988an a li dijî kurdan', 'Rojnameya kurdî ya serdema destpêkê ya ku li Silêmaniyê hatiye çapkirin', '"Rojnameya Jiyan" → rojnameya kurdî ya serdema destpêkê ya ku li Silêmaniyê hatiye çapkirin.', true),
  ('66524261-cf8c-4f09-bea0-f62bb5c6d6b0'::uuid, 'Di zanîna erdnîgariyê de der barê ''Hewler ovası'' de ya rast kîjan e?', 'Platoya kevirî ya ji lavên Qerecdaxê çêbûyî', 'Gola tektonîk a di nav sînorên Xarpêtê de', 'Gola bendavê ya li ser Çemê Diyalayê hatiye avakirin', 'Deşta çandiniyê ya herî berhemdar a Başûrê Kurdistanê', '''Hewler ovası'' → Deşta çandiniyê ya herî berhemdar a Başûrê Kurdistanê.', true),
  ('66dac624-21b1-40f7-ad26-3c1947b3cb88'::uuid, '"Çemê Botanê" di erdnîgariyê de çi îfade dike?', 'Rêzeçiyayên herî asê yên erdnîgariya Dêrsimê', 'Çemê ku ji herêma Sêrtê derbas dibe û diherike Dîcleyê', 'Çemê har ê ku çiyayên Colemêrgê diqelêşe û diherike', 'Platoya kevirîn a ku lavên Qerecdaxê çêkirine', '"Çemê Botanê" → çemê ku ji herêma Sêrtê derbas dibe û diherike Dîcleyê.', true),
  ('6756e9d5-f1b1-4b17-97ea-52a77ca260e5'::uuid, 'Li jêr ji bo "şerta xweseriya xwecihî" pênasa rast kîjan e?', 'Ku civak karên xwe yên herêmî bi xwe birêve bibin', 'Desthilata parlamena herêmî ya ku dikare qanûnên xwe çêbike', 'Belgeya navneteweyî ya ku hêza rêveberiyên herêmî zêde dike', 'Rêveberiya ku ji şaredarî û meclisên herêmî pêk tê', '"Şerta xweseriya xwecihî" belgeya navneteweyî ye ku hêza rêveberiyên herêmî zêde dike.', true),
  ('67695ada-9670-48ee-966f-1f20576c5a68'::uuid, 'Derbarê "Celadet Bedirxan" de agahiya rast kîjan e?', 'Rojnameya kurdî ya yekem a ku di 1898an de li Qahîreyê hat çapkirin', 'Kovara kurdî ya yekem a ku bi alfabeya latînî hat çapkirin', 'Weşanger û rewşenbîrê ku alfabeya kurdî pêş xistiye', 'Rêberê bihêz ê mîrektiya Soran ê bi leqeba kor', '"Celadet Bedirxan" weşanger û rewşenbîr e ku alfabeya kurdî pêş xistiye.', true),
  ('681d8a46-5fdb-483d-b904-c686a22a0d3f'::uuid, 'Cigerxwîn bi xeta xwe ya sosyalîst li ser kîjan mijaran rawestiya?', 'Entrîkayên serayê', 'Kedê, xizaniyê û têkoşînê', 'Werzişî', 'Serpêhatiyên deryayî', 'Cigerxwîn di xeteke sosyalîst-realîst de li ser mijarên ked, xizanî û têkoşînê rawestiya.', true),
  ('690c3e76-8adb-4699-b685-d5b0865960af'::uuid, 'Kovara Hawar bi taybetî bi kîjan tevkariyê tê bibîranîn?', 'Pêşketina cureyên wek roman û rojnameyê di serdema modern de', 'Ji ber ku gelek nivîskar li derveyî welêt berhem dane', 'Belavbûna alfabeya kurdî ya li ser bingehê latînî', 'Veguhastina devkî ya çîrok û hêkayeyên bi awaz', 'Derdora Hawarê ji bo standardbûna alfabeya kurdî ya latînî û nivîsa kurmancî ya modern girîng e.', true),
  ('69123251-a0bb-431d-a2f0-d8c2950cee5a'::uuid, 'Di lêkolîna dîroka Kurd û Kurdistanê de kronolojî çi tê wateyê?', 'Azadî û berxwedana li dijî zilmê', 'Tevgera neteweyî ya kurdên Iraqê', 'Rêzkirina bûyeran li gorî rêza demê', 'Serdema osmanî ya sedsala 16an', 'Di lêkolîna dîroka Kurd û Kurdistanê de kronolojî tê wateya rêzkirina bûyeran li gorî demê.', true),
