  ('add1038d-a93a-41c1-8a5c-cddc468964bd'::uuid, 'Wêneyê Salvador Dalí yê ''The Persistence of Memory'' di kîjan salê de hate qedandin?', '1951.', '1921.', '1931.', '1941.', 'The Persistence of Memory di 1931-an de hate qedandin.', false),
  ('adf06e09-d51b-445d-b1d2-fdd7eab3d9fc'::uuid, 'Têgeha ''mala dengbêjan'' çi pêk tîne?', 'Strana epîk an evînî ya ku dengbêj dibêjin', 'Yek ji nûnerên herî naskirî yên kevneşopiya dengbêjiya jinên kurd', 'Mekana çandî ya li Wan û Amedê ku dengbêj lê têne guhdarkirin', 'Stranên gelêrî yên lezgîn û rîtmîk ên ku li govendan têne lêxistin', '''Mala dengbêjan'': Mekana çandî ya li Wan û Amedê ku dengbêj lê têne guhdarkirin.', true),
  ('ae0ed2b6-7464-4631-8208-4b2a3b4f3a0f'::uuid, 'Kevneşopiya dengbêjiyê berê bi giranî li kîjan cihan zindî dihat girtin?', 'Jiyana herêmî û parvekirin', 'Odeyên gundan û dîwan', 'Sor, kesk û zer', 'Bi kevneşopiyê ve girêdayî ye', 'Dengbêj bi awayekî kevneşopî li odeyên gundan û dîwanan diciviyan û hunera xwe pêşkêş dikirin.', true),
  ('af2d4bc2-330d-444f-9204-83fe355cc04f'::uuid, 'Encama girîng a parvebûna nasnameya kurdî li welatên cuda çi ye?', 'Ziman, siyaset û polîtîkayên çandî li gorî welatan ji hev cuda bûne', 'Hemû kurd xwedî heman statuya fermî ne', 'Qet dîasporayek çênebûye', 'Zarava bi temamî ji holê rabûne', 'Ji ber ku kurd li dewletên cuda yên wekî Tirkiye, Iraq, Îran û Sûriyeyê dijîn, ezmûnên wan ên maf, polîtîkaya ziman û rewşa siyasî ji hev cuda bûne.', true),
  ('af633f6d-5a0b-4a20-a026-4d91981102fc'::uuid, 'Romanên kurdî yên pêşîn bi piranî di kîjan serdemê de derketine?', 'Sedsala 15an', 'Sedsala 12an', 'Sedsala 20an', 'Sedsala 17an', 'Romana kurdî bi giranî cureyeke modern e ku di sedsala 20an de pêş ketiye.', true),
  ('b0368480-51dd-41fd-ae56-3f10c41fdba4'::uuid, 'Li jêr ji bo ''Aram Tîgran'' kîjan rast e?', 'Hosteyê muzîkê yê bi eslê xwe ermenî ku bi stranên kurdî tê naskirin', 'Amûra bayê ya kevneşopî ku şivan jî lê dixin', 'Dengbêjê herî navdar ê ku muzîka kurdî cîhanê daye nasîn', 'Cureyê muzîkê ku zêdetir li ser evîn û mêraniyê tê gotin', '''Aram Tîgran'': Hosteyê muzîkê yê bi eslê xwe ermenî ku bi stranên kurdî tê naskirin.', true),
  ('b07939bf-e714-4788-8530-40725d07b524'::uuid, 'Di lawazbûna mîrnişînên kurdî de di sedsala 19an de kîjan pêvajo diyarker bû?', 'Seferên vîkîngan', 'Polîtîkayên navendîkirinê yên osmaniyan û qacaran', 'Reformên komara Romayê', 'Sefera moxolan a li ser Japonyayê', 'Mîrnişînên wek Baban, Botan û Soran di nav navendîkirina împeratoriyan û reqabetên herêmî de paşve çûn.', true),
  ('b1e14806-f471-495e-bcf9-54c5ffe49e74'::uuid, 'Di çarçoveya dîrokê de ''Tevgera Barzanî'' tê çi wateyê?', 'Tevgera neteweyî ya ku li Başûrê Kurdistanê bi salan dom kir', 'Mîrê kurd ê ku di sedsala 19an de ji bo xweseriyê têkoşî', 'Dewleta mezin a ku ji aliyê Selaheddînê Eyûbî ve hatiye avakirin', 'Aktîvîsta jin a kurd a ku ji aliyê rejîma Iraqê ve hatiye îdamkirin', '''Tevgera Barzanî'': Tevgera neteweyî ya ku li Başûrê Kurdistanê bi salan dom kir.', true),
  ('b1ee19b4-4899-4440-9a24-e5b6bb5d2884'::uuid, 'Ji bo muzîkê derbarê ''tembûrê'' de vebijêrka rast kîjan e?', 'Hunermendê rîtmê ku bi hostayî erbaneyê an defê lê dixe', 'Lêdanên rêkûpêk ên ku bingeha muzîkê pêk tînin', 'Amûra têlî ya ku di muzîka gelêrî ya kurdî de herî pîroz tê hesibandin', 'Muzîka devkî ya ku di şevên zivistanê de tê gotin', '''Tembûr'': Amûra têlî ya ku di muzîka gelêrî ya kurdî de herî pîroz tê hesibandin.', true),
  ('b29b768e-c690-4de3-9927-947d4b5e337c'::uuid, 'Kîjan ji van peyvên kurmancî tê wateya ''sandalye''?', 'Kursî', 'Dapîr', 'Diçim', 'Were!', '"sandalye" bi Kurmancî "kursî" ye.', false),
  ('b36261d9-f8f7-40a5-80a5-34d13d7e7d06'::uuid, '"Helbest" bi Tirkî çi ye?', 'Tiyatro', 'Roman', 'Masal', 'Şiir', '"Helbest" bi Tirkî tê wateya şiir; ji helbestvan re jî şair tê gotin.', false),
  ('b39ea118-38ba-4b35-8566-749b3f320c4c'::uuid, 'Xwarina şîla û birinc di çavkaniyên geştiyariyê yên Herêma Kurdistanê de çawa tê nasîn?', 'Xwarina kevneşopî ya ku bi mirîşk û birincê tê çêkirin', 'Tenê vexwarineke sar', 'Cureyeke govendê', 'Alfabeyeke nivîsê', 'Di rûpela geştiyariyê ya Hikûmeta Herêma Kurdistanê de şîla û birinc wekî xwarineke kevneşopî ya bi mirîşk û birincê tê binavkirin.', true),
  ('b62dccb3-8607-4376-a157-e30dc5f8bae1'::uuid, 'Peyva ''Başûr'' di binavkirina herêmî ya kurdî de bi piranî qala kîjan derê dike?', 'Başûrê Kurdistanê / Kurdistana Iraqê', 'Bakurê Kurdistanê', 'Rojavayê Kurdistanê', 'Diasporaya Qefqasyayê', '''Başûr'' tê wateya başûr û di bikaranîna siyasî-çandî ya berbelav de Kurdistana Iraqê nîşan dide.', true),
  ('b6b39fe2-6896-4877-abbe-63abbea22b9a'::uuid, 'Ji aliyê wêjeyê ve ji bo ''Dîwana Melayê Cizîrî'' gotina rast kîjan e?', 'Helbestvanê dîwana klasîk ê ku li mîrnişîna Colemêrgê gihîştiye', 'Helbestvan û nivîskarê modern ê navdar ê Rojhilatê Kurdistanê', 'Kovara wêjeyî ya ku li Şamê bi alfabeya latînî derdiket', 'Dîwana helbestan a navdar a ku evîna mistîk û felsefeyê dihewîne', '''Dîwana Melayê Cizîrî'': Dîwana helbestan a navdar a ku evîna mistîk û felsefeyê dihewîne.', true),
  ('b744fafa-c1f0-4b1b-aefe-3fa9f41fba45'::uuid, 'Mesûd Barzanî demeke dirêj serokatî li kîjan herêmê kir?', 'Cihguherîna civakan', 'Herêma Kurdistana Iraqê', 'Qefqasya', 'Tevgera neteweyî ya kurd a Iraqê', 'Mesûd Barzanî demeke dirêj serokê Herêma Kurdistana Iraqê bû.', true),
  ('b75cfe1f-afe7-437f-a515-ca8fe088e6c8'::uuid, '"Sêwas" bilêvkirina kurdî ya kîjan bajarî ye?', 'Tokat', 'Malatya', 'Sivas', 'Erzincan', '"Sêwas" bilêvkirina kurdî ya bajarê Sivasê ye.', false),
