  ('b818cad6-982a-430a-bdd2-a2b67c9dd62b'::uuid, 'Li jêr ji bo ''tûtik'' kîjan rast e?', 'Çanda pêşkêşkirina dew û avê', 'Kevneşopiya muzîk û rîtuel/awazê', 'Amûra kevneşopî ya dişibe bilûrê', 'Xurtkirina girêdanên civakî', '''tûtik'' → Amûra kevneşopî ya dişibe bilûrê.', true),
  ('b81b8adf-21ab-4c9d-9a76-a7db3d734840'::uuid, 'Di hevoka ''Ev diyariya mamosteyê ye'' de kîjan pêwendî tê bikaranîn?', 'ezafe', 'neyînî', 'pirs', 'ferman', 'Ezafe nav û raveker an xwedîtiyê bi hev ve girê dide.', false),
  ('b8ef84a2-e8f7-4e69-a0f2-b068c1d457ce'::uuid, 'Komara Mehabadê ya ku di sala 1946an de hatiye damezrandin çiqas dom kir?', 'Çend meh (temen kurt)', 'Nêzîkî sî salan', 'Nêzîkî deh salan', 'Nêzîkî sedsaleyekê', 'Komara Mehabadê di sala 1946an de hat damezrandin û tenê çend mehan dom kir.', true),
  ('b9dd36a9-b973-4b46-94ec-9af0b69abd3d'::uuid, 'Kîjan ji gelên kevnar ên ku bav û kalên kurdan têne hesibandin e?', 'Med', 'Maya', 'Vîkîng', 'Romayî', 'Medya gelek caran wekî yek ji bav û kalên dîrokî yên kurdan tê binavkirin.', true),
  ('ba1d668b-ca31-47eb-ace5-5b7c2892c7a9'::uuid, 'Peyva ''kilam'' di çanda kurdî de herî zêde bi çi ve tê girêdan?', 'Stran/gotina bi awaz', 'Kana kevir', 'Yekîneya pere', 'Wesayîta deryayê', 'Kilam di çarçoveya dengbêjî û muzîka gelêrî de dikeve qada wateyê ya gotina bi awaz û strana gelêrî.', true),
  ('be040a44-8247-403b-b17b-16d0c966ffdf'::uuid, 'Di çarçoveya cografyayê de ''Hazar gölü'' çawa divê bê fêmkirin?', 'Çemê har ê ku çiyayên Colemêrgê diqelêşe', 'Çiyayê volkanîk ê çalak ê xwedî gola kraterê', 'Çemê mezin ê ku jiyanê dide Mezopotamyayê', 'Gola tektonîk a li ser sînorê Xarpêtê', '''Hazar gölü'' → Gola tektonîk a li ser sînorê Xarpêtê.', true),
  ('be47690b-4d59-4a00-afad-4dc580c32094'::uuid, 'Ji hejmara 24an pê ve, nivîsên Kurmancî yên Hawarê tenê bi kîjan alfabeyê hatin çapkirin?', 'Bi alfabeya latînî', 'Bi alfabeya erebî-farisî', 'Bi alfabeya kîrîlî', 'Bi alfabeya yewnanî', 'Ji hejmara 24an pê ve, li gorî çavkaniyê, Hawarê tenê alfabeya latînî bi kar anî.', false),
  ('becf1db7-c861-4a3b-9abc-a99f51e3a23a'::uuid, 'Ji hawîrdora ku dengbêj lê dicivin û performansa xwe lê dikin re çi tê gotin?', 'Dîwan', 'Stran', 'Meydan', 'Sûriye', 'Ji hawîrdora ku dengbêj lê kom dibin û bi rêzê performansa xwe lê dikin re dîwan (dîwana dengbêjan) tê gotin.', false),
  ('c0071d6c-418b-4405-8a76-9fe958373a4a'::uuid, 'Gotina Rojhilat di termînolojiya siyasî-çandî ya kurdî de bi giştî kîjan herêmê vedibêje?', 'Herêma kurdî ya li Îranê', 'Herêma kurdî ya li Sûriyeyê', 'Herêma kurdî ya li Iraqê', 'Diyasporaya Ewropayê', 'Rojhilat bi wateya ''rojhilat'' navê herêmî yê kurdî ye ku ji bo Kurdistana Îranê tê bikaranîn.', true),
  ('c093ca9c-150b-4af4-963b-9669f01a7f72'::uuid, 'Derbarê ''nanê sêlê'' de ravekirina rast kîjan e?', 'Bi kevneşopiya devkî ve girêdayî ye', 'Şorba kevneşopî ya heft dexlan', 'Nanê ku li ser sêlê tê pijandin', 'Kevneşopiya muzîk, rîtuel û awazan', '''Nanê sêlê'' → nanê ku li ser sêlê tê pijandin.', true),
  ('c0a69407-02bc-412c-ae09-b942f3b63632'::uuid, '''Kovara Hawarê'' çawa tê pênasekirin?', 'Yekem lêkolînerê ku tore û edetên kurdî berhev kiriye', 'Yekem kovara kurdî ya bi alfabeya latînî hatiye çapkirin', 'Yekem rojnameya kurdî ya di sala 1898an de li Qahîreyê hatiye çapkirin', 'Mîrgeha kurdî ya li başûrê Gola Wanê desthilat kiriye', '''Kovara Hawarê'' → yekem kovara kurdî ya bi alfabeya latînî hatiye çapkirin.', true),
  ('c1c0235a-8f4c-4a29-b4bf-bb02649ab615'::uuid, 'Ji şeva ku berî dawetê hene tê danîn re çi tê gotin?', 'Şeva dawetê', 'Şeva henê', 'Şeva çiyê', 'Şeva dengbêjan', 'Ji şeva ku berî dawetê hene tê danîn re "şeva henê" tê gotin.', false),
  ('c1d93607-e4de-4a16-b41d-2e230b3c8549'::uuid, 'Dema behsa ''Rojnameya Kurdistanê'' tê kirin, mebesta çi ye?', 'Serokkomarê Komara Kurdî ya Mehabadê', 'Rêberê bihêz ê mîrgeha Soranê yê bi leqeba kor', 'Yekem rojnameya kurdî ya di sala 1898an de li Qahîreyê hatiye çapkirin', 'Xanedana kurdî ya serdema navîn a navenda Diyarbekirê', '''Rojnameya Kurdistanê'' → yekem rojnameya kurdî ya di sala 1898an de li Qahîreyê hatiye çapkirin.', true),
  ('c360c9dc-74f9-4932-8865-10ea5a994919'::uuid, 'Kîjan ji van amûran amûreke kevneşopî ya kurdî ya bi têl e?', 'Zurna', 'Bilûr', 'Tembûr', 'Erbane', 'Tembûr amûreke bi têl e; bilûr û zurna tên pifkirin, erbane jî tê lêxistin.', false),
  ('c3d278c4-592b-438e-b282-bef36bbb0725'::uuid, 'Derbarê ''Nalî'' de kîjan rast e?', 'Helbestvanê dîwanê yê herî mezin ê dibistana helbesta klasîk a soranî', 'Yekem dîroknas û helbestvana jin a kurd ku di dîrokê de dîwan nivîsiye', 'Ekola edebî û fikrî ya ku Ehmedê Xanî daye destpêkirin', 'Yekem ferhenga kurdî ya ku Ehmedê Xanî nivîsiye', '''Nalî'' → helbestvanê dîwanê yê herî mezin ê dibistana helbesta klasîk a soranî ye.', true),
  ('c548abdf-6d44-4635-806f-aa7c5249846c'::uuid, 'Parvekirina xwarinê li ser sifreyên kurdî bi sînîyeke mezin an bi pêşkêşkirina hevbeş çi xurt dike?', 'Rêkûpêkiya ezmûna bêdeng', 'Tecrîda takekesî ya temam', 'Qedexeya xwarinê', 'Girêdanên civakî û malbatî', 'Pêşkêşkirin û parvekirina hevbeş pratîkên çandî ne ku têkiliyên malbat, cîrantî û mêvanperweriyê xurt dikin.', true),
  ('c5bcb73f-2ee1-489f-954c-bf3cc86243f6'::uuid, 'Sê rengên bingehîn ên li ser alaya kurdî kîjan in?', 'Reş, sor û zer', 'Sor, spî û kesk', 'Kesk, zer û mor', 'Şîn, spî û sor', 'Li ser alaya kurdî rengên sor, spî û kesk û di navendê de rojek heye.', true),
  ('c6001e3b-e032-4048-b623-59337390d5fa'::uuid, 'Di warê erdnîgariyê de ''Çiyayê Sipanê'' çi îfade dike?', 'Geliyê li Dêrsimê yê di statuya parka neteweyî de', 'Zozanên bilind ên ku çavkaniya gelek çeman lê ye', 'Çiyayê volkanîk ê vemirî yê li bakurê Gola Wanê', 'Deşta berhemdar a ku deştên Cizîr û Silopiyê digire nava xwe', '''Çiyayê Sipanê'' → çiyayê volkanîk ê vemirî yê li bakurê Gola Wanê ye.', true),
  ('c734abc1-2dad-4c54-ad1c-07fd661e9dac'::uuid, 'Kurd bi awayê herî giştî wekî çi cureyê civakê tên pênasekirin?', 'Tenê bajarekî kevnar', 'Tenê komeke pîşeyî', 'Tenê klûbeke werzişê', 'Civakeke etnîk û zimanî', 'Britannica kurdan wekî civakeke etnîk û zimanî pênase dike.', true),
  ('c803ec17-b39e-4161-8d0e-15b133efe592'::uuid, 'Ji çîrok û serpêhatiyên ku zivistanan tên vegotin re bi kurmancî bi giştî çi tê gotin?', 'Cejn', 'Ap', 'Bûk', 'Çîrok', '''Çîrok'' tê wateya çîrok û meselê; cejn pîrozbahî ye, ap û bûk têkiliyên malbatî ne.', true),
  ('c81fe848-d71e-490e-8955-114cc8a13cb9'::uuid, 'Di civaka kurd de avahiyên eşîran di dîrokê de xwedî kîjan fonksiyonê bûne?', 'Tora rêxistina civakî, ewlehî, hilberîn û têkiliyên siyasî', 'Tenê dekora şanoyê', 'Tu fonksiyona civakî tune ye', 'Fîloya deryayê', 'Avahiyên eşîran di dîrokê de parçeyek ji torên piştevaniya civakî û desthilata siyasî bûne.', true),
  ('c8480e43-dd5c-4997-b388-ffa5df784469'::uuid, 'Encama girîng a geşedana parçekirî ya nasnameya kurdî li welatên cuda çi ye?', 'Xwedîbûna hemû kurdan a heman statuya fermî', 'Cudabûna polîtîkayên ziman, siyaset û çandê li gorî welatan', 'Çênebûna tu diyasporayê', 'Wendabûna temam a zaravayan', 'Jiyana kurdan li dewletên cuda yên wekî Tirkiye, Iraq, Îran û Sûriyeyê ezmûnên maf, polîtîkaya ziman û statuya siyasî cuda kiriye.', true),
  ('c87f3ab0-f78c-4956-a52c-9a6a717fb0a9'::uuid, 'Têgeha ''beşdariya rasterast'' çi pêk tîne?', 'Girtina biryaran li yekîneyên herî nêzîkî gel', 'Beşdarbûna gel bi xwe di biryarên siyasî de', 'Wekî pirsgirêka nasname, ziman, statu û mafan', 'Qonaxa bidawîkirina rewşa nakok bi diyalogê', '''Beşdariya rasterast'' → beşdarbûna gel bi xwe di biryarên siyasî de ye.', true),
  ('c8802423-30c6-4871-b16f-24fed8109a87'::uuid, 'Di dîrokê de ''Erdewan Zaxoyî'' kî ye?', 'Gotina stranê an lêxistina hunermendekî tenê', 'Muzîkjenê şoreşger ê hezkirî yê herêma Behdînanê', 'Lêdanên birêkûpêk ên ku bingeha muzîkê pêk tînin', 'Şêweya dengbêjiya serbest-rîtmî ya ku kilam pê tên xwendin', '''Erdewan Zaxoyî'': Muzîkjenê şoreşger ê hezkirî yê herêma Behdînanê.', true),
  ('c8a809ec-3539-4181-90fc-dcfb4470a97e'::uuid, 'Li gorî pênaseyê ''Komara Mehabadê'' kîjan e?', 'Yekem lêkolînerê ku tore û edetên kurdî berhev kirine', 'Belge an tiştê ji serdema xwe mayî (çavkaniya seretayî)', 'Peymana ku sînorê Osmanî û Sefewiyan diyar kiriye', 'Yekem dewleta kurdî ya bi temenekî kurt ku di sala 1946an de hatiye avakirin', '''Komara Mehabadê'' → yekem dewleta kurdî ya bi temenekî kurt ku di sala 1946an de hatiye avakirin.', true),
  ('c8d50936-baab-4d94-8d9c-1c47186aaa76'::uuid, '"Gelî" çi ye?', 'Çiyayê bilind', 'Newala teng', 'Gola kûr', 'Deşta fireh', 'Peyva "gelî" tê wateya vadiyeke an jî newaleke teng.', false),
  ('c96f9cf2-9484-4fbe-afcd-902dbcccd1a4'::uuid, 'Derbarê ''deholê'' de ravekirina rast kîjan e?', 'Awaza ku bi rêzkirina dengan li pey hev çê dibe', 'Awaza bêamûr û bixweber', 'Amûra rîtmê ya bi zirneyê re tê lêxistin', 'Dengê efsanewî yê muzîka klasîk a Behdînanê', '''Dehol'' → amûra rîtmê ya bi zirneyê re tê lêxistin e.', true),
  ('c994b228-b1b4-441a-9cbd-b235c0f131e6'::uuid, 'Ji aliyê muzîkê ve ji bo ''muzîka govendê'' îfadeya rast kîjan e?', 'Hunermendê hosta yê ermenî yê bi stranên kurdî tê naskirin', 'Stranên gelêrî yên bijû û rîtmîk ên di govendan de tên lêxistin', 'Amûra bayî ya kevneşopî ya ku şivan jî lê dixin', 'Cureyê muzîkê yê ku zêdetir li ser evîn û mêraniyê tê gotin', '''Muzîka govendê'' → stranên gelêrî yên bijû û rîtmîk ên di govendan de tên lêxistin e.', true),
  ('cb1170c1-c535-47c1-acf7-f4658d82ad14'::uuid, '''Rêûresma şabaşê'' tê çi wateyê?', 'Veguhestina muzîkê ya bi têkiliya hosta-şagirt dimeşe', 'Edeta xelatkirina muzîkjenan bi avêtina pereyan', 'Dengê bihêz ê ku kurd jê re ''şahê dengbêjan'' dibêjin', 'Kilama gelêrî ya navdar a ku efsaneyê vedibêje', '''Rêûresma şabaşê'' → edeta xelatkirina muzîkjenan bi avêtina pereyan e.', true),
  ('cb19f0d5-3614-4a2e-a2c7-12cd5e5abfd9'::uuid, 'Di çarçoveya muzîkê de ''Kardeş Türküler'' tê çi wateyê?', 'Koma ku muzîka kurdî di hawîrdoreke pirçandî de pêşkêş dike', 'Muzîka devkî ya di şevên zivistanê yên sohbetê de tê pêşkêşkirin', 'Muzîka rîtmîk û meqamî ya herêma Şirnex û Cizîrê', 'Strangotin an lêxistina hunermendekî tenê', '''Kardeş Türküler'' → koma ku muzîka kurdî di hawîrdoreke pirçandî de pêşkêş dike.', true),
  ('ce9a851a-6cdf-4eaf-baa8-c4eb10f853c0'::uuid, 'Berhema klasîk a kurdî Mem û Zîn herî zêde bi kîjan nivîskar/helbestvan re tê têkildarkirin?', 'Dante', 'Nazim Hikmet', 'Ehmedê Xanî', 'Tolstoy', 'Mem û Zîn wekî yek ji berhemên herî girîng ên Ehmedê Xanî di wêjeya kurdî de tê qebûlkirin.', true),
  ('ceabbdb3-78f5-4a51-bfb3-b545576322f3'::uuid, '''Aram Tigran'' kî ye?', 'Cihê çandî yê li Wan û Diyarbekirê ku dengbêj lê tên guhdarkirin', 'Cureyê muzîkê yê ku zêdetir li ser evîn û mêraniyê tê gotin', 'Hunermendê hosta yê ermenî yê bi stranên kurdî tê naskirin', 'Ji nûnerên herî navdar ên kevneşopiya dengbêjiya jin a kurd', '''Aram Tigran'' → hunermendê hosta yê ermenî yê bi stranên kurdî tê naskirin e.', true),
  ('cef7ff5d-b81b-4d15-ba09-b9f92cc10cf7'::uuid, 'Çend tîrêjên rojê di navenda Ala Kurdistanê de hene?', '21', '12', '7', '40', 'Tava li ser alê 21 tîrêj hene; Jimara 21 jî bi Newrozê (21ê Adarê) ve girêdayî ye.', false),
  ('cef9da2a-6105-408d-baa7-7eece1905818'::uuid, 'Soranî li Iraq û Îranê bi piranî bi kîjan pergala nivîsê tê nivîsandin?', 'Alfabeya gurcî', 'Qet li derveyî alfabeya latînî ya Hawarê nayê nivîsandin', 'Nivîsa runî', 'Alfabeya kurdî ya bingeh-erebî', 'Soranî li Iraq û Îranê bi berfirehî bi alfabeya kurdî ya bingeh-erebî tê nivîsandin.', true),
  ('cf26b950-4d42-44b7-a4b9-a99e600f673d'::uuid, 'Israra li ser "bêyî çayê vexwarin neçe" ji mêvan re bi çandî çi nîşan dide?', 'Mêvanperwerî û xwesteka têkilîdanînê', 'Dijminatî', 'Tenê pêdiviya fermî ya belgeyan', 'Cezayê bêdengiyê', 'Pêşkêşkirina çayê parçeyeke germ a çanda sohbet û mêvanperweriyê di jiyana rojane de ye.', true),
  ('cf332166-780c-4aac-b575-35b2cf40aaf9'::uuid, 'Wateya peyva "çem" bi Tirkî kîjan e?', 'çöl', 'nehir', 'tepe', 'mağara', '"çem" bi Tirkî tê wateya nehir an jî ırmak.', false),
  ('d0088dd7-ec08-4944-baa8-40ccdd543877'::uuid, 'Beranbera "bina/ev" bi Kurmancî çi ye?', 'Xanî', 'Reng', 'Rast', 'Deşt', 'Beranbera "bina/ev" bi Kurmancî "xanî" ye.', false),
  ('d079479a-bd55-4ce3-9847-6b75005d7273'::uuid, 'Çima kilîm û berhemên hunandî yên kurdî di lêkolînên çandî de girîng in?', 'Ji ber ku tu motîfan nagirin nava xwe', 'Ji ber ku tenê ji plastîk tên çêkirin', 'Ji ber ku zanîna jiyana rojane, motîf û estetîka herêmî hildigirin', 'Ji ber ku tenê kodên nermalavê ne', 'Hunandin û motîf nîşanên bîra herêmî, hilberîn û cîhana estetîk a civakan hildigirin.', true),
  ('d079daa5-7d9c-4007-8cb0-914118248a8d'::uuid, 'Bi giştî peyva Rojhilat di termînolojiya siyasî-çandî ya kurdî de behsa kîjan herêmê dike?', 'Diyasporaya Ewropayê', 'Herêma kurdî ya Sûriyeyê', 'Herêma kurdî ya Iraqê', 'Herêma kurdî ya Îranê', 'Rojhilat bi wateya "rojhilat" navê herêma kurdî ya Kurdistana Îranê ye.', true),
  ('d262b148-9fc9-42b6-9262-cb39a1f1943a'::uuid, 'Ji bo ''Nûbihara Biçûkan'' şiroveya herî rast kîjan e?', 'helbestvanekî girîng ê edebiyata klasîk a kurdî', 'dîwana helbestan a navdar a evîna mîstîk û felsefeyê', 'ferhenga kurdî ya yekem ku Ehmedê Xanî nivîsiye', 'nivîskarê ku Şerefname û Mem û Zîn wergerandiye bo soranî', '''Nûbihara Biçûkan'' ferhenga kurdî ya yekem e ku Ehmedê Xanî nivîsiye.', true),
  ('d2ae1e87-3873-44be-8b8c-8108fccb9350'::uuid, 'Di dîroka kurdî de piştî serdema mîrektiyan kîjan pêvajo hatiye jiyîn?', 'Împeratoriya Med (berî Persan)', 'lêkolîna dîrokê bi bermahiyên madî', 'YNK (Yekîtiya Niştimanî ya Kurdistanê)', 'navendîkirin û rêveberiya rasterast', 'Piştî serdema mîrektiyan bi polîtîkayên navendîkirinê pêvajoya rêveberiya rasterast hatiye jiyîn.', true),
  ('d30c7f03-e395-4bc7-b2de-b9ef05c48f86'::uuid, '''Şerefname'' di kîjan warî de wekî yekem xebata berfireh tê hesibandin?', 'pêjgeha kurdî', 'mîmariya kurdî', 'muzîka kurdî', 'dîroka kurdî', 'Şerefname di warê dîrok û mîrektiyên kurdan de yekem berhema berfireh tê dîtin.', true),
  ('d3800eef-1baa-478b-9f9d-493f78efd8bf'::uuid, 'Derbarê ''Qedrîcan'' de di edebiyatê de vebijarka rast kîjan e?', 'yek ji helbestvanên klasîk ên herî kevin ên edebiyata kurdî', 'ji ber ku xebatên ziman û alfabeyê belav kiriye', 'ekola edebî û fikrî ya Ehmedê Xanî daye destpêkirin', 'nivîskarê di helbesta modern û pexşana kurdî de şop hiştî', '''Qedrîcan'' nivîskarek e ku di helbesta modern û pexşana kurdî de şop hiştiye.', true),
  ('d46963b8-ca04-420c-9390-aaf9de090819'::uuid, 'Wateya peyva "newal" bi Tirkî kîjan e?', 'kıyı', 'ada', 'zirve', 'vadi', '"newal" bi Tirkî tê wateya vadi.', false),
  ('d4df3273-1242-4d12-bf20-15c5fe805227'::uuid, 'Wateya "heyv" (hîv) bi Tirkî çi ye?', 'Yıldız', 'Güneş', 'Ay', 'Bulut', '"Heyv/hîv" bi Tirkî tê wateya "(gökyüzündeki) ay".', false),
  ('d596f0be-684e-4f9d-9451-9308d0eb3cbf'::uuid, 'Wateya peyva "îro" bi Tirkî kîjan e?', 'baba', 'soğuk', 'kitap', 'bugün', '"îro" bi Tirkî tê wateya bugün.', false),
  ('d5a1a4e5-9589-42b2-9ee4-c89870fbf8ab'::uuid, 'Kîjan pênase bi ''mixalefeta demokratîk'' re li hev tê?', 'xwerêveberiyeke ji dewletê derbas dibe û alternatîf e bo wê', 'meclisên gel ên biryarên herêmî lê tên girtin', 'parastina mafan bi qanûnê', 'kanalên lêgerîna mafan li meclisê û li kolanê', '''Mixalefeta demokratîk'' kanalên lêgerîna mafan li meclisê û li kolanê ye.', true),
  ('d5f30622-2fcd-466c-a058-f164920b73ac'::uuid, '''Mîrektiya Soran'' tê çi wateyê?', 'berhema dîroka kurdî ya ku Şeref Xan nivîsiye', 'êrişa kîmyayî ya 1988an a li dijî kurdan', 'jenosîda rejîma Iraqê ya li dijî kurdan', 'mîrektiyeke ku navenda wê Rewandiz e û hêza leşkerî kom kiriye', '''Mîrektiya Soran'' mîrektiyeke ku navenda wê Rewandiz e û hêza leşkerî kom kiriye.', true),
  ('d60af5d9-ca46-40d1-b138-83447fd3895d'::uuid, 'Derbarê ''Yaşar Kemal'' de di edebiyatê de vebijarka rast kîjan e?', 'ji ber ku gelek nivîskar li derveyî welat berhem dane', 'zimanhez û nivîskarê ku pirtûkên rêzimana kurdî nivîsiye', 'romannivîsê hosta yê bi eslê kurd ê li cîhanê tê naskirin', 'nivîskarê ku Şerefname û Mem û Zîn wergerandiye bo soranî', '''Yaşar Kemal'' romannivîsekî hosta yê bi eslê kurd e ku li cîhanê tê naskirin.', true),
  ('d7421302-3b67-4e1f-84c4-2b2598ce7b9c'::uuid, 'Derbarê ''Şakiro'' de şiroveya rast kîjan e?', 'dengê bihêz ê kurd jê re ''şahê dengbêjan'' dibêjin', 'cureyekî din ê meqamê di muzîka gelêrî ya kurdî de', 'stranbêjî an lêxistina hunermendekî bi tenê', 'awaza ku ji rêzkirina dengan a li pey hev pêk tê', '''Şakiro'' dengê bihêz e ku kurd jê re ''şahê dengbêjan'' dibêjin.', true),
  ('d75d578a-0d17-4b7c-88e4-ea1ed00c0adf'::uuid, 'Piştî kîjan şerî Selahedîn Orşelîm vegerand?', 'Şerê Çanakkaleyê', 'Şerê Enqereyê', 'Şerê Hittînê (1187)', 'Şerê Milazgirê', 'Di sala 1187an de piştî Şerê Hittînê Selahedîn Orşelîm vegerandiye.', true),
  ('d75d5b87-00e1-4b51-a573-cecaab9a58d6'::uuid, 'Derbarê ''meqamên Botanê'' de agahiya herî rast kîjan e?', 'dengbêjê ku tomarên destpêkê yên muzîka kurdî çêkiriye', 'yekem hunermenda jin a kurd a ku plak dagirtiye', 'ozanê ku hestên neteweyî yên gelê kurd tîne ziman', 'muzîka ritmîk û meqamî ya herêma Şirnex û Cizîrê', '''Meqamên Botanê'' muzîka ritmîk û meqamî ya herêma Şirnex û Cizîrê ye.', true),
  ('d80ad048-777e-43ab-8a15-67a676e2dfb1'::uuid, 'Di dîrokê de ''Şêx Mehmûdê Berzencî'' kî ye?', 'yekem rojnamegerê kurd ê ku rojnameya Kurdistanê derxistiye', 'êrişa kîmyayî ya 1988an a li dijî kurdan', 'qirkirina rejîma Iraqê ya li dijî kurdan', 'rêberê ku li Iraqê xwe wekî qralê Kurdistanê îlan kiriye', '''Şêx Mehmûdê Berzencî'' rêber e ku li Iraqê xwe wekî qralê Kurdistanê îlan kiriye.', true),
  ('d8c80b2f-0abc-4dbe-a1f2-a29f8c981de4'::uuid, 'Têgeha ''Tevgera Barzanî'' çi pêk tîne?', 'efserê ku li ser navê cemiyeta Xoybûnê pêşengiya leşkerî kiriye', 'qirkirina rejîma Iraqê ya li dijî kurdan', 'tevgera neteweyî ya li Başûrê Kurdistanê ya bi salan dom kiriye', 'eyaleta îdarî ya demkurt a di 1847an de li Osmaniyan hatiye avakirin', '''Tevgera Barzanî'' tevgera neteweyî ya li Başûrê Kurdistanê ya bi salan dom kiriye.', true),
  ('d9202257-e8a5-47c0-aba4-4b280a2bf425'::uuid, 'Di hevoka ''Îro ez zû rabûm'' de ''îro'' çi nîşan dide?', 'cih', 'dem', 'kes', 'awa', 'Peyva ''îro'' demê nîşan dide (wateya wê ''ev roj'' e).', false),
  ('d9ece07c-c571-4086-93e8-5f1acc1746c0'::uuid, 'Kîjan têgeh ''Nûbihara Biçûkan'' rast şirove dike?', 'ekola edebî û fikrî ya ku Ehmedê Xanî daye destpêkirin', 'zêdekirina xuyabûna kurdî di nivîs, weşan, perwerde û hilberîna dîjîtal de', 'bi weşana yekem rojnameya kurdî Kurdistanê ve girêdayî ye', 'ferhenga kurdî ya yekem a ku Ehmedê Xanî nivîsiye', '''Nûbihara Biçûkan'' ferhenga kurdî ya yekem e ku Ehmedê Xanî nivîsiye.', true),
  ('da042ef5-be19-4db8-a8d7-a809228c2963'::uuid, 'Di çarçoveya Dîrokê de ''Mervaniler'' çawa divê bê fêmkirin?', 'Xanedana kurdî ya serdema navîn ku navenda wê Amed e', 'Belge an tiştê ji serdema xwe mayî', 'Weşanvan û rewşenbîrê ku alfabeya kurdî pêş xistiye', 'Peymana ku cografyaya kurdî di navbera çar dewletan de parve kiriye', '''Mervaniler'' → Xanedana kurdî ya serdema navîn ku navenda wê Amed e.', true),
  ('da88afd2-575a-4bd5-98c3-43756cfdcc2c'::uuid, '''Çiyayê Sîpan'' nêzîkî kîjan golê ye?', 'Gola Xwê', 'Gola Egirdirê', 'Gola Wanê', 'Gola Beyşehirê', 'Çiyayê Sîpan li bakurê Gola Wanê ye.', true),
  ('dbceb8de-79a6-4177-aabb-2f6bc0e90305'::uuid, 'Ji bo ''rojnameya Kurdistanê'' pênaseya derbasdar kîjan e?', 'weşanger û rewşenbîrê ku alfabeya kurdî pêş xistiye', 'yekem lêkolînerê ku adet û toreyên kurdan kom kiriye', 'yekem rojnameya kurdî ya di 1898an de li Qahîreyê hatiye çapkirin', 'yekem kovara kurdî ya bi alfabeya latînî hatiye çapkirin', '''Rojnameya Kurdistanê'' yekem rojnameya kurdî ye ku di 1898an de li Qahîreyê hatiye çapkirin.', true),
  ('dd1b2819-ac7e-4084-bfa4-9aead74d40ce'::uuid, '"Baş" (qenc) bi Tirkî tê çi wateyê?', 'İyi', 'Kötü', 'Küçük', 'Büyük', '"Baş" (qenc) bi Tirkî tê wateya "iyi".', false),
  ('dde482a5-3d8d-42b7-8e72-3fe21697fefa'::uuid, 'Di çarçoveya Cografyayê de ''Bingöl dağları'' çawa divê bê fêmkirin?', 'Zozanên bilind ên ku kaniya gelek çeman in', 'Çiyayê volkanîk ê vemirî yê li bakurê Gola Wanê', 'Çiyayên ku cografyaya Kurdistanê seranser dibirrin', 'Deşta mezin a çandiniyê ya ku şaxên Firatê av didinê', '''Bingöl dağları'' → Zozanên bilind ên ku kaniya gelek çeman in.', true),
  ('defc2583-9773-4bf5-87bb-e73a0a5d4ba9'::uuid, 'Kîjan cih ''Urmiye gölü'' rast tarîf dike?', 'Deyşta mezin a çandiniyê ya ku şaxên Firatê av didinê', 'Rêzeçiyayên herî asê yên cografyaya Dêrsimê', 'Çemê ku di bin sûrên Amedê re derbas dibe', 'Hewzeya gola xwê ya li Rojhilatê Kurdistanê', '''Urmiye gölü'' → Hewzeya gola xwê ya li Rojhilatê Kurdistanê.', true),
  ('df3fee78-2509-4f2a-afbf-12bfc72ed274'::uuid, 'Li jêr kîjan têgeh ''Yüksekova'' rave dike?', 'ava ku ji sînorên Qers û Îdirê derbas dibe û diherike Xezarê', 'deşta tektonîk a bilind a li Colemêrgê', 'lûtkeya herî bilind a li ser sînorê Kurdistana Iraqê', 'ji ber ku yek ji kevintirîn warên bicihbûna bênavber ên cîhanê ye', '''Yüksekova'' deşta tektonîk a bilind a li Colemêrgê ye.', true),
  ('df66fa71-91cb-4520-b06c-34b943558021'::uuid, 'Kîjan têgeh ''kilim motifleri'' rast şirove dike?', 'Motîfa qesra zêrîn a di çîrokan de', 'Bi dawet û pîrozbahiyê ve girêdayî ye', 'Îlahiyên olî / metnên pîroz ên devkî', 'Sembolên çandî û bîra rengan', '''kilim motifleri'' → Sembolên çandî û bîra rengan.', true),
  ('dfa1547c-7f97-4642-99a1-cac570c3a692'::uuid, 'Di wêjeya siyasetê de ''daxwaza statuyê'' cih nagire.', 'Rast', 'Çewt', null, null, 'Îdiaya di pirsê de ya derbarê ''daxwaza statuyê'' de ne rast e; bersiva rast ''Çewt'' e.', true),
  ('e16a8137-a468-4e02-ada6-3ea535b93097'::uuid, '''Şerefname'' di kîjan pêkhateya siyasî de hatiye nivîsandin?', 'li Misira Antîk', 'di serdema Sovyetê de', 'di serdema Romayê de', 'di serdema Osmaniyan de (sedsala 16an)', 'Şerefname di serdema Osmaniyan de, di dawiya sedsala 16an de (1597) hatiye nivîsandin.', true),
  ('e1be4ee6-7d34-4399-8215-9f649b8c96e6'::uuid, 'Di parastina destkariyeke kevneşopî de, çima tenê parastina berhemê bes nake?', 'Ji ber ku berhem divê ji hildêrên wê bê veqetandin.', 'Ji ber ku divê zanîn, teknîk û rêbaza hînkirina wê jî bê parastin.', 'Ji ber ku tenê rengê berhemê wateya mîrasê dide.', 'Ji ber ku hînkirin nikare di destkariyê de rolek bilîze.', 'Mîrasa destkarî bi zanîn û jêhatîbûna hildêrên wê ve zindî ye; parastina berhemê bê parastina pêvajoyê têr nake.', false),
  ('e234ac1c-09f4-4ebe-934c-c414cd104eca'::uuid, 'Li ser sifreyên kurdî parvekirina xwarinê bi sêniya mezin an pêşkêşiya hevpar çi xurt dike?', 'qedexeya xwarinê', 'tecrîda takekesî ya temam', 'girêdanên civakê û malbatê', 'rêkûpêkiya ezmûna bêdeng', 'Pêşkêşî û parvekirina hevpar peywendiyên malbatê, cîrantiyê û mêvandariyê xurt dike.', true),
  ('e24a93c1-1b84-4058-9a47-4b346cb07cd9'::uuid, 'Kîjan di muzîkê de têgeha ''çeng'' rast bi cih dike?', 'amûra mîna harpê ya ku di muzîka Mezopotamyaya antîk û ya kurdî de tê bikaranîn', 'hunermendê ku bayê rock û cazê tîne nav muzîka kurdî', 'cihê çandî yê li Wan û Amedê ku dengbêj lê tên guhdarkirin', 'amûra lêdanî ya ku di muzîka kurdî ya tesewufê û ya gelêrî de tê bikaranîn', '''Çeng'' amûra mîna harpê ye ku di muzîka Mezopotamyaya antîk û ya kurdî de tê bikaranîn.', true),
  ('e29fc4c4-8920-492b-a776-fc2ece5e0682'::uuid, 'Peymana Sevrê ya sala 1920an ji bo pirsa kurdî çima pir tê bibîranîn?', 'Ji ber ku wê kurdî qedexe kiriye', 'Ji ber ku tê de xweseriya kurdan û bendên muhtemel ên serxwebûnê hatine nîqaşkirin', 'Ji ber ku wê Kela Hewlêrê xistiye lîsteya UNESCOyê', 'Ji ber ku wê Komara Mahabadê ava kiriye', 'Sevr, di nîqaşên siyasî yên kurdî yên nûjen de ji ber nîqaşên xweseriyê û statuya muhtemel gelek tê bi bîr anîn.', true),
  ('e2da46a3-2f81-4904-9ea3-09d3cbbc3f31'::uuid, 'Di dengbêjiyê de amûra bingehîn a hunermendî pir caran çi ye?', 'Tenê defa elektronîk', 'Deng û bîr', 'Mîmîka bêdeng', 'Makîneya çapê', 'Dengbêj bîra civakî bi deng, awaz û vegotinên dirêj vediguhezînin.', true),
  ('e376a3d3-aecd-48c7-8323-cb16e8a8bd5b'::uuid, 'Di çarçoveya wêjeyê de Ekola Hawarê çawa divê bê fêmkirin?', 'Ji helbestvanên klasîk ên kurdî yên herî kevn ên tên nasîn yek', 'Tevgera wêjeyî ya ku ronakbîriya kurdî û alfabeya latînî belav kiriye', 'Helbestvanê dîwanê yê herî mezin ê dibistana helbesta klasîk a soranî', 'Ji destanên devkî yên kurdî yên herî xemgîn yek', 'Ekola Hawarê tevgera wêjeyî ya ku ronakbîriya kurdî û alfabeya latînî belav kiriye ye.', true),
  ('e37ed043-e501-4214-927f-8c8567bd8794'::uuid, 'Derbarê ''Bohtan Emirliği'' de vebijêrka rast kîjan e?', 'Di serdema Osmaniyan de', 'Begtiya kurdî ya girîng ku navenda wê Cizîr e', 'Dîroka xanedan û begtiyên kurdî', 'Serdema Osmanî-Sefewî', '''Bohtan Emirliği'' → Begtiya kurdî ya girîng ku navenda wê Cizîr e.', true),
  ('e43d9ef5-31fa-4bd7-afb5-7a4705114370'::uuid, '''stranên Şakiro'' tê çi wateyê?', 'Stranên gelêrî yên coşdar û rîtmîk ên ku di govendan de tên lêxistin', 'Yekem hunermenda jin a kurd a ku plaq dagirtiye', 'Yek ji nûnerên herî naskirî yên kevneşopiya dengbêjiya jinên kurd', 'Kilamên destanî yên dirêj ên ku Şakiro gotine', '''stranên Şakiro'' kilamên destanî yên dirêj ên ku Şakiro gotine ne.', true),
  ('e53cb10d-ee8d-41a9-8a55-332543edc83e'::uuid, 'Rojnameya kurdî ya pêşîn Kurdistan di kîjan salê de hatiye weşandin?', '1918', '1928', '1898', '1948', 'Kurdistan, rojnameya kurdî ya pêşîn e û di sala 1898an de derketiye.', true),
  ('e54477d7-3c7c-4650-bb6a-3867fe7a36cc'::uuid, 'Navê Amed di bikaranîna kurdî de herî zêde bi kîjan bajarî ve tê girêdan?', 'Mêrdîn', 'Riha', 'Wan', 'Diyarbekir', 'Amed di bikaranîna siyasî û çandî ya kurdî de navê berbelav ê Diyarbekirê ye.', true),
  ('e5708630-f461-4aa6-914d-5c0c60c867e8'::uuid, 'Paytexta Macaristanê kîjan bajar e?', 'Cairo', 'Budapest', 'Asunción', 'Canberra', 'Li gorî daneyên strukturî yên Wikidata, paytexta Macaristanê Budapest e.', false),
  ('e5b8a12f-6ce7-45b9-b5b4-91624face78f'::uuid, 'Melayê Bateyî kî ye?', 'Nivîskarê romana kurdî ya pêşîn a bi navê Şivanê Kurd', 'Belavbûna alfabeya kurdî ya li ser bingehê latînî', 'Helbestvan û alimê dîn ê ku cara pêşîn mewlûda zazakî nivîsiye', 'Helbestvanê klasîk ê ku Mewlûda Şerîf bi kurdî nivîsiye', 'Melayê Bateyî helbestvanê klasîk ê ku Mewlûda Şerîf bi kurdî nivîsiye ye.', true),
  ('e62ae870-9dae-4924-97c1-df7927b7b5ab'::uuid, 'Di hevoka "Ez diçim malê" de lêker (fiil) kîjan e?', 'Diçim', 'Ez', 'Malê', 'Hîç yek', 'Lêkera ''diçim'' di vê hevokê de lêker e.', false),
  ('e6e4fa82-1492-48f7-933e-fb0ced4b107f'::uuid, 'Derbarê kovara Hawarê de vebijarka rast kîjan e?', 'Peymana ku erdnîgariya kurdan di navbera çar dewletan de parve kiriye', 'Derdora Colemêrg û Cizîrê ya çiyayî', 'Kovara kurdî ya pêşîn a ku bi alfabeya latînî hatiye çapkirin', 'Rojnameya kurdî ya pêşîn a ku di sala 1898an de li Qahîreyê hatiye çapkirin', 'Kovara Hawarê kovara kurdî ya pêşîn e ku bi alfabeya latînî hatiye çapkirin.', true),
  ('e8276db2-b139-4e8a-86d7-b3d12f42750d'::uuid, 'Derbarê Abdulla Goran de ji bo wêjeyê vebijarka rast kîjan e?', 'Ji damezrînerên şanoya kurdî, yek ji nivîskarên lîstikan', 'Rojnameya kurdî ya ku bi salan li Êrîvanê hatiye weşandin', 'Pêşengê nûjenbûna helbesta kurdî ya soranî', 'Belavbûna alfabeya kurdî ya li ser bingehê latînî', 'Abdulla Goran pêşengê nûjenbûna helbesta kurdî ya soranî ye.', true),
  ('e843f111-7349-44ca-bbb8-c0e26fbe9583'::uuid, 'Wateya "Şev" bi Tirkî çi ye?', 'Gündüz', 'Sabah', 'Gece', 'Akşam', '"Şev" tê wateya gece (mînak: şev baş = iyi geceler).', false),
  ('e9100141-df1c-48a6-b4ec-9d0d9ad9a956'::uuid, 'Derbarê şevbêrkê de agahiya herî rast kîjan e?', 'Cilên dirêj ên rengîn û qatbiqat ên jinan', 'Civînên sohbetê yên ku di şevên zivistanê de tên lidarxistin', 'Daxwaza mêvanperweriyê û têkilîdanînê', 'Îranî û gelek gelên din (wek Newrozê)', 'Şevbêrk civînên sohbetê ne ku di şevên zivistanê de tên lidarxistin.', true),
  ('e98e6503-8e56-4fc6-a263-c1730e6fb2d3'::uuid, 'Erdnîgariya Kurdistanê bi giştî bi kîjan du sîstemên çiyayî yên mezin re tê bibîranîn?', 'Tawros û Zagros', 'Alp û Karpat', 'Hîmalaya û Pamîr', 'Atlas û Rîf', 'Herêma dîrokî ya ku nifûsa kurdan lê zêde ye, bi giranî bi kembera çiyayî ya li derdora Tawros û Zagrosan ve girêdayî tê dîtin.', true),
  ('ea54376f-ecbe-4c89-9db1-2cbed0c90575'::uuid, 'Derbarê muzakereyê de ravekirina rast kîjan e?', 'Rêbaza çareserkirina pirsgirêkan bi rêya diyalogê', 'Nûnertiya wekhev û rêveberiya hevbeş a jin û mêran', 'Xwereveberiyeke ku dewletê derbas dike û alternatîfa wê ye', 'Bi azadiya jinan û xwereveberiya piralî', 'Muzakere rêbaza çareserkirina pirsgirêkan bi rêya diyalogê ye.', true),
  ('eb1e308b-6258-4c2c-b3db-5b1fb066f630'::uuid, 'Mafên mirovan di mijara siyasetê de çi vedibêje?', 'Prensîba parvekirina wekhev a çavkanî û mafan', 'Parastina komên cuda yên li hember piraniyê', 'Mafên gerdûnî yên her kesî ji zayînê ve hene', 'Şêweyê protestoya aştiyane ya li dijî yasayên neheq', 'Mafên mirovan mafên gerdûnî ne ku her kes ji zayînê ve xwediyê wan e.', true),
  ('eb43fdda-6420-4dd7-85e5-e9e7a86097d3'::uuid, 'Derbarê hevserokatiya partiyê de agahiya rast çi ye?', 'Sîstema ku jin di partiyan de bi awayekî wekhev xwedî gotin e', 'Dayîna biryaran bi desteyan, ne bi rêberekî tekane', 'Mafên protesto, rêxistinbûn û azadiya derbirînê', 'Parastina komên cuda yên li hember piraniyê', 'Hevserokatiya partiyê sîstemeke wisa ye ku jin di partiyan de bi awayekî wekhev xwedî gotin in.', true),
  ('eb70f191-51b2-493a-a13e-baaf6179486a'::uuid, 'Derbarê beşdariya sivîl de agahiya herî rast kîjan e?', 'Destûreke azadîxwaz a ku hemû beşên cuda dihewîne', 'Rewşa xwe-rêvebirin û biryardayîna herêmî', 'Desthilata parlemanoya herêmî ya ku dikare yasayên xwe çêbike', 'Bi rêya komele û însiyatîfan mudaxeleya rêveberiyê', 'Beşdariya sivîl bi rêya komele û însiyatîfan mudaxeleya rêveberiyê ye.', true),
  ('ebf6e8c3-bf3c-4e2b-98be-65b5bcf17a17'::uuid, 'Kurmancî bi piranî bi kîjan sîstema nivîsê tê nivîsîn?', 'Nivîsa bizmarî', 'Tu alfabeyek ji bilî alfabeya kîrîlî', 'Alfabeya Hawarê ya bi bingehê latînî', 'Sîstema kanaya japonî', 'Kurmancî, bi taybetî di çarçoveya Tirkiye û Sûriyeyê de, bi alfabeya Hawarê ya bi bingehê latînî belav bûye.', true),
  ('ec0ba388-6ff3-43a6-be93-2dc59c070c5b'::uuid, 'Ji bo zazakî û goranî di zimannasiyê de nêzîkatiya herî rast kîjan e?', 'Ziman an zaravayên îranî yên ku girêdana wan a sosyo-çandî ya xurt bi civakên kurd re heye, lê dabeşkirina wan a zimannasî cihê nîqaşê ye', 'Tevahî zimanên latînî ne', 'Zimanê çînî-tîbetî ye', 'Şaxên îngilîziya modern in', 'Zazakî û goranî awayên axaftinê yên îranî ne ku bi nasnameya kurd ve tên girêdan, lê dabeşkirina wan a zimannasî cihê nîqaşê ye.', true),
  ('ed66455d-7685-479c-b927-3641e9a1ef41'::uuid, 'Amadekariyên zivistanê û hişkkirin di jiyana kevneşopî ya kurd de çima girîng in?', 'Ji ber ku di avhewaya çiyayî de berxwedana demsalî û ewlehiya xwarinê peyda dikin', 'Ji ber ku tenê wekî xeml tên bikaranîn', 'Ji ber ku hemû xwarinan qedexe dikin', 'Ji ber ku berhemên deryayê zêde dikin', 'Di şert û mercên çiyayî û demsalî de hişkkirin, parastin û amadekariyên zivistanê ji bo aboriya malê girîng in.', true),
  ('edbe47bc-4829-48ed-a7e7-2cb10d68f864'::uuid, 'Perwerdeya bi zimanê dayikê çima girîng tê dîtin?', 'Wek pirsa nasname, ziman, statu û mafan', 'Tevlîbûna ji jêr û biryardayîna herêmî', 'Ji bo veguhestina nasname û çandê bo nifşên nû', 'Naskirina hemwelatîbûna wekhev û mafan', 'Perwerdeya bi zimanê dayikê ji bo veguhestina nasname, ziman û çandê bo nifşên nû girîng tê dîtin.', true),
  ('eeaa6e24-8c9b-45e7-890e-5f1af666e6e4'::uuid, 'Derbarê destana Memê Alan de agahiya rast çi ye?', 'Ji destanên devkî yên kurdî yên herî xemgîn yek', 'Bi weşandina rojnameya kurdî ya pêşîn a Kurdistanê ve girêdayî ye', 'Destana gelêrî ya ku Ehmedê Xanî jê îlham girtiye ji bo Mem û Zînê', 'Di serdema nûjen de pêşketina cureyên wek roman û rojnameyê', 'Destana Memê Alan destana gelêrî ye ku Ehmedê Xanî jê îlham girtiye ji bo Mem û Zînê.', true),
  ('ef0b51ce-0beb-4823-9c28-fe482d0444df'::uuid, 'Ji aliyê wêjeyê ve ji bo Elî Herîrî gotina rast kîjan e?', 'Nivîskarê ku Şerefname û Mem û Zînê wergerandiye soranî', 'Ekola wêjeyî û ramanî ya ku Ehmedê Xanî daye destpêkirin', 'Ji helbestvanên klasîk ên kurdî yên herî kevn ên tên nasîn yek', 'Helbestvanê dîwanê yê herî mezin ê dibistana helbesta klasîk a soranî', 'Elî Herîrî ji helbestvanên klasîk ên kurdî yên herî kevn ên tên nasîn yek e.', true),
  ('ef3de8dc-71ea-468c-8bbd-ccc850a9c41c'::uuid, '"welat" (Kurmancî) bi Tirkî tê çi wateyê?', 'ülke/vatan', 'nasılsın?', 'bilmiyorum', 'kız kardeş', '"welat" kelimesi "ülke/vatan" demektir.', false),
  ('f0402e6d-0468-428c-99df-847950574b3c'::uuid, 'Ferhad û Şîrîn di mijara wêjeyê de çi vedibêje?', 'Ekola wêjeyî û ramanî ya ku Ehmedê Xanî daye destpêkirin', 'Ji helbestvanên klasîk ên kurdî yên herî kevn ên tên nasîn yek', 'Nivîskarê ku Şerefname û Mem û Zînê wergerandiye bo soranî', 'Çîroka evînê ya klasîk ku di kevneşopiya devkî ya kurdî de jî tê vegotin', 'Ferhad û Şîrîn çîroka evînê ya klasîk e ku di kevneşopiya devkî ya kurdî de jî tê vegotin.', true),
  ('f0a1837d-d07e-4f22-89ea-6d13f435c06c'::uuid, 'Derbarê ''Erdewan Zaxoyî'' de ya rast kîjan e?', 'Dengê bi hêz ê ku kurd jê re ''şahê dengbêjan'' dibêjin', 'Muzîkjenê şoreşger ê hezkirî yê herêma Behdînanê', 'Veguhastina muzîkê ya bi têkiliya hoste-şagirt dimeşe', 'Saza têlî ya herî pîroz a muzîka gelêrî ya kurdî', '''Erdewan Zaxoyî'': Muzîkjenê şoreşger ê hezkirî yê herêma Behdînanê.', true),
  ('f1884636-1a0c-47f9-a71c-d628afb5369b'::uuid, 'Derbarê Elî Herîrî de agahiya rast kîjan e?', 'Akademîsyenek ku li ser ziman û wêjeya kurdî dixebite', 'Helbestvanê dîwanê yê herî mezin ê dibistana helbesta klasîk a soranî', 'Ji helbestvanên klasîk ên kurdî yên herî kevn ên tên nasîn yek', 'Dîrokzan û helbestvana kurd a pêşîn a ku dîwan nivîsiye', 'Elî Herîrî ji helbestvanên klasîk ên kurdî yên herî kevn ên tên nasîn yek e.', true),
  ('f1feaae0-efc7-4ae5-933e-e72c9c6fb9d1'::uuid, 'Berambera rast a biwêja ''şevbêrk müziği'' kîjan e?', 'Muzîka devkî ya di sohbetên şevên zivistanê de tê gotin', 'Şêweya muzîka lîrîk a taybet a herêmên Qers, Agirî û Wanê', 'Dengbêjê ermenî yê ku muzîka devkî ya kurdî berhev kiriye', 'Veguhastina muzîkê ya bi têkiliya hoste-şagirt dimeşe', '''şevbêrk müziği'' → Muzîka devkî ya di sohbetên şevên zivistanê de tê gotin.', true),
  ('f317f077-7b6b-4f55-bac7-a45907c2ef97'::uuid, 'Kîjan têgeh "hevserokatiya partiyê" di siyasetê de rast bi cih dike?', 'mafê parastinê li dadgehên serbixwe û bêalî', 'lihevhatina rêveberiyê bi razîbûna gel û hiqûqê re', 'sîstema hevserokatiyê ya ku jin tê de xwedî gotineke wekhev e', 'vîna çareserkirina nakokiyan bi diyalogê li şûna çekan', '"Hevserokatiya partiyê" tê wateya sîstemekê ku jin tê de xwedî gotineke wekhev e.', true),
  ('f3636d63-c9ff-4bcd-be97-ee6c0c61141c'::uuid, 'Wateya "pîr" û "şêx" di pêkhateya civaka êzidî de çi ye?', 'Amûrên muzîkê', 'Çînên olî-civakî', 'Cureyên xwarinê', 'Herêmên erdnîgarî', 'Di civaka êzidî de pîr û şêx çînên kevneşopî ne ku erkên olî-civakî hildigirin.', true),
  ('f3715ad5-66bf-4201-abe5-709103cb2249'::uuid, 'Di bankeya pirsan de qada "etîketan" ji bo kîjan karê teknîkî bi kêr tê?', 'Ji bo tunekirina bersiva rast', 'Ji bo danîna sîstema lêgerînê, parzûnkirinê û dubarekirina kesane', 'Ji bo hilanîna çavkaniyan', 'Ji bo tevlihevkirina rûpelên PDFê', 'Etîket di sepanê de ji bo parzûnkirina li gorî kategoriyan û dubarekirina mijarên lawaz bi kêr tê.', true),
  ('f3db1d2d-0510-464b-8d3c-61e9acfa7be2'::uuid, 'Kîjan têgeh "vegotina çîrokan" rast şirove dike?', 'reqasa gelêrî ya kevneşopî ya sê-lingî', 'modela hunandina porê kurdî ya kevneşopî', 'konê ku ji mûyê bizina reş hatiye çêkirin', 'vegotina ku ji nifşekî vediguheze nifşekî din', '"Vegotina çîrokan" tê wateya vegotina ku ji nifşekî vediguheze nifşekî din.', true),
  ('f492222d-8bcc-408b-aaf1-3ef69c21965a'::uuid, 'Beranbera peyva "ateş" bi Kurmancî çi ye?', 'Diran', 'Dûr', 'Agir', 'Kanî', 'Beranbera "ateş" bi Kurmancî "agir" e.', false),
  ('f4dc4b1a-0be5-459c-b311-9c9675b6e751'::uuid, 'Li jêr bersiva rast a derbarê ''ezgiyên Serhedê'' de kîjan e?', 'Şêwaza muzîka lîrîk a taybet a herêmên Qers, Agirî û Wanê', 'Şêwaza vokala bi rîtma azad a ku kilam pê tên gotin', 'Dengbêjê ku qeydên destpêkê yên muzîka kurdî çêkiriye', 'Hunermendê rîtmê yê ku bi hostayî erbane an defê dixe', '''ezgiyên Serhedê'' şêwaza muzîka lîrîk a taybet a herêmên Qers, Agirî û Wanê ye.', true),
  ('f5587a9c-64de-482d-b2b7-b44c79085306'::uuid, 'Çima UNESCO di hînkirina AI de li ser ''ramana rexneyî'' radiweste?', 'Ji bo ku tenê lez û hêsaniya sepanê bê pîvan.', 'Ji bo ku xwendekar hemû encamên AI bê pirsîn rast qebûl bike.', 'Ji bo ku AI ji hemû pêvajoyên biryardan bê derxistin.', 'Ji bo ku xwendekar karibe encamên AI bi delîl, sînor, bandor û armancên wan re binirxîne.', 'Çarçoveya UNESCO xwendekaran wek bikarhênerên berpirsiyar û afirîner dibîne ku divê encam û bandorên AI bi nêrîneke rexneyî binirxînin.', false),
  ('f5dc3609-c9e7-448b-b204-01f5d9aa084d'::uuid, 'Kîjan pênase "Mistefa Barzanî" rast dide nasîn?', 'Operasyona leşkerî û krîza li herêma Dêrsimê', 'Rêberê leşkerî û siyasî yê efsanewî yê tevgera kurd', 'Mîrê kurd ê di sedsala 19an de ji bo xweseriyê têkoşiya', 'Êrîşa kîmyayî ya sala 1988an li dijî kurdan', '"Mistefa Barzanî": rêberê leşkerî û siyasî yê efsanewî yê tevgera kurd.', true),
  ('f61e42d1-25f8-469a-85c7-8b56fee27e4a'::uuid, '"Mihemed Taha Akreyî" bi kîjan taybetmendiya xwe tê nasîn?', 'Hunermendê gelêrî yê klasîk ê populer ê Behdînanê', 'Şêwaza dengbêjiyê ya bi rîtma azad ku kilam pê tên gotin', 'Şêwaza muzîka lîrîk a taybet a herêmên Qers, Agirî û Wanê', 'Yekem hunermenda jin a kurd ku di muzîka kurdî de plak dagirtiye', '"Mihemed Taha Akreyî": hunermendê gelêrî yê klasîk ê populer ê Behdînanê.', true),
  ('f6360310-2462-4e50-911f-6ac9c4350133'::uuid, 'Gotina ''şila û birinc'' di çavkaniyên geştiyariyê yên KRGê de çawa tê nasandin?', 'Xwarina kevneşopî ya ku bi mirîşk û birincê tê çêkirin', 'Tenê vexwarineke sar', 'Cureyeke reqsê', 'Alfabeyeke nivîsê', 'Rûpela geştiyariyê ya KRGê ''şila û birinc'' wekî xwarineke kevneşopî ya li ser bingeha mirîşk û pilavê bi nav dike.', true),
  ('f65d52b3-0631-4e92-b1e4-b82e389af58a'::uuid, 'Li gorî UNESCO, ziman di kevneşopiyên devkî de çi rolê dilîze?', 'Wek astengiyek ku divê ji vegotinê bê rakirin.', 'Wek navgîna veguhastina çîrok, gotin, zanîn û bîra civakî.', 'Wek amûrek ku tenê ji bo belgeyên fermî ye.', 'Wek tiştekî ku bi çandê re têkildar nîne.', 'UNESCO kevneşopiyên devkî û zimanê ku wan digihîne nifşên din wek beşên girîng ên mîrasa bê-maddî dide naskirin.', false),
  ('f6832bf0-9d74-4d47-9984-1ff908204727'::uuid, 'Vexwarina ji cureyê dew/doxê bi kîjan madeya sereke ve girêdayî ye?', 'Tenê qalikê lîmonê', 'Lîqora qehweyê', 'Mast', 'Ardê lazûtê', 'Dew/dox vexwarineke hênikker e ku bingeha wê mast e û bi kevneşopiyeke vexwarinê ve girêdayî ye.', true),
  ('f6d1ee25-61a2-48ef-b0dc-d221a7c57075'::uuid, 'Kîjan ji van peyvên kurmancî tê wateya "aile"?', 'Axaftin', 'Newal', 'Pisîk', 'Malbat', '"aile" bi Kurmancî "malbat" e.', false),
  ('f6eabb89-f8bc-4d89-bc69-755181f4d135'::uuid, 'Kîjan pênase "operasyona Enfalê" rast dide nasîn?', 'Qirkirina rejîma Iraqê li dijî kurdan', 'Rêberê ku li Iraqê xwe wek qralê Kurdistanê îlan kir', 'Efserekî ku li ser navê cemiyeta Xoybûnê pêşengiya leşkerî kir', 'Navê dîrokî yê antîk ê Amedê û keleha wê', '"Operasyona Enfalê": qirkirina rejîma Iraqê li dijî kurdan.', true),
  ('f6efd917-3ee1-4f85-9623-8395c615a450'::uuid, 'Wateya Tirkî ya peyva "kaxez" kîjan e?', 'kağıt', 'doğru', 'baba', 'git!', 'Kurmancî "kaxez" ≈ "kağıt".', false),
  ('f70a4bec-0675-4e3f-a0f1-f07c190cc9e5'::uuid, 'Vexwarina ji cureyê dew/doxê bi kîjan madeya sereke ve girêdayî ye?', 'Ardê lazûtê', 'Lîqora qehweyê', 'Tenê qalikê lîmonê', 'Mast', 'Dew/dox vexwarineke hênikker e ku bingeha wê mast e û bi kevneşopiyeke vexwarinê ve girêdayî ye.', true),
  ('f738cc17-86a4-4095-aa16-02beee20e0f0'::uuid, 'Di çarçoveya Dîrokê de ''Ağrı İsyanları'' çawa divê bê fêmkirin?', 'Mîrê kurd ê di sedsala 19an de ji bo xweseriyê têkoşiyayî', 'Berxwedana li dora Çiyayê Agiriyê di salên 1927-1930an de', 'Qirkirina rejîma Iraqê li dijî kurdan', 'Çalaka jin a kurd a ji aliyê rejîma Iraqê ve hatiye bidarvekirin', '''Ağrı İsyanları'': Berxwedana li dora Çiyayê Agiriyê di salên 1927-1930an de.', true),
  ('f7a78ad8-ae64-4248-8055-a36db386f517'::uuid, 'Derbarê "antîkapîtalîzmê" de zanîna rast kîjan e?', 'sîstema jiyana alternatîf a li dijî modernîteya kapîtalîst', 'beşdarbûna civaka herêmî di pêvajoyên biryardana xwe de', 'têkiliya di navbera serdestiyê û wêrankirina xwezayê de', 'helwesta li dijî mantiqê qezenc û kedxwariyê yê kapîtalîzmê', '"Antîkapîtalîzm" tê wateya helwesta li dijî mantiqê qezenc û kedxwariyê yê kapîtalîzmê.', true),
  ('f80a01aa-1f18-430e-88b3-4e4142f3e832'::uuid, 'Yekemîn romanên kurdî di kîjan serdemê de derketine?', 'Sedsala 15an', 'Sedsala 12an', 'Sedsala 17an', 'Sedsala 20an', 'Romana kurdî cureyekî nûjen e ku bi giranî di sedsala 20an de pêş ketiye.', true),
  ('f80cd6df-2c46-4aa4-bdd6-151cfa3d6ee5'::uuid, 'Ji bo "beşdarbûna siyasî" pênaseya derbasdar kîjan e?', 'bikaranîna zimanê dayikê li qadên fermî û giştî', 'rêvebirina civakê ji aliyê xwe ve bê zexta derve', 'beşdarbûna welatiyan di pêvajoyên biryardayînê de', 'rewşa rêvebirin û biryardayîna herêmî ya bi xwe', '"Beşdarbûna siyasî" tê wateya beşdarbûna welatiyan di pêvajoyên biryardayînê de.', true),
  ('f881cd5a-3a4f-4c25-a197-0a68bbc75370'::uuid, 'Li jêr kîjan têgeh "xweseriya siyasî" rave dike?', 'beşdarbûna welatiyan di pêvajoyên biryardayînê de', 'rêveberiya ku ji şaredarî û meclisên herêmî pêk tê', 'beşdarbûna di rêveberiyê de bi komele û însiyatîfan', 'desthilata parlamena herêmî ya ku dikare qanûnên xwe çêbike', '"Xweseriya siyasî" tê wateya desthilata parlamena herêmî ya ku dikare qanûnên xwe çêbike.', true),
  ('f8a95bcf-1d7b-40eb-bc3d-713e3fb0dd83'::uuid, '"Pertew Begê Hekarî" bi kîjan taybetmendiya xwe tê nasîn?', 'Helbestvanê dîwanê yê klasîk ê ku li mîrnişîna Hekariyê mezin bûye', 'Nivîskarê ku Şerefname û Mem û Zîn wergerandiye soranî', 'Dîwana helbestan a navdar a ku evîna mîstîk û felsefeyê dihewîne', 'Ji ber ku gelek nivîskar li derveyî welat berhem didin', '"Pertew Begê Hekarî": helbestvanê dîwanê yê klasîk ê ku li mîrnişîna Hekariyê mezin bûye.', true),
  ('fa044f84-2882-4c08-822e-3798a94364aa'::uuid, 'Di zanîna wêjeyê de derbarê "Mestûre Erdelan" de ya rast kîjan e?', 'yekem dîrokzan û helbestvaneke jin a kurd ku di dîrokê de dîwan nivîsiye', 'mezintirîn helbestvanê dîwanê yê dibistana helbesta klasîk a soranî', 'dîwana helbestan a navdar a ku evîna mîstîk û felsefeyê dihewîne', 'zimanzan û nivîskara ku pirtûkên rêzimana kurdî nivîsîne', '"Mestûre Erdelan": yekem dîrokzan û helbestvaneke jin a kurd ku di dîrokê de dîwan nivîsiye.', true),
  ('fa4f9eb5-ab7f-4aec-921b-f2e4d762d50e'::uuid, 'Di zanîna erdnîgariyê de derbarê "çemê Firatê" de ya rast kîjan e?', 'hewza gola sodî ya herî mezin a cîhanê', 'niştecihê gir ê dîrokî yê mîrateya UNESCOyê', 'çiyayê volkanîk ê çalak ê ku gola kraterê lê heye', 'çemê mezin ê ku jiyanê dide Mezopotamyayê', '"Çemê Firatê" tê wateya çemê mezin ê ku jiyanê dide Mezopotamyayê.', true),
  ('fa754b26-1d3c-4ad2-a0ab-572abccb9a5f'::uuid, 'Peymana ku şûna Sevrê girt û statuya kurdan tê de tune kîjan e?', 'Sedsala 19an', 'Dîcle û Firat', 'Îslama sunnî', 'Lozan (1923)', 'Peymana Lozanê ya 1923yan şûna Sevrê girt û tê de tu statu ji bo kurdan tune bû.', true),
  ('faac8e77-6ea8-45cb-97bb-dae61b0971ce'::uuid, 'Li jêr ji bo "Ferhad û Şîrîn" kîjan rast e?', 'Çîroka evînê ya klasîk ku di kevneşopiya devkî ya kurdî de jî tê vegotin', 'Yek ji destanên herî xemgîn ên wêjeya devkî ya kurdî', 'Ji ber ku xebatên ziman û alfabeyê belav kiriye', 'Yek ji helbestvanên klasîk ên herî kevin ên wêjeya kurdî', '"Ferhad û Şîrîn": çîroka evînê ya klasîk ku di kevneşopiya devkî ya kurdî de jî tê vegotin.', true),
  ('faaf8b0f-890e-4bd0-b274-06411ff7ab96'::uuid, 'Derbarê "muzîka şevbêrkê" de bijardeya rast kîjan e?', 'veguhestina muzîkê ya ku bi têkiliya hoste-şagirt dimeşe', 'muzîkjenê şoreşger ê hezkirî yê Behdînanê', 'muzîka devkî ya ku di sohbetên şevên zivistanê de tê gotin', 'hunermendê rîtmê yê ku erbane an defê bi hostayî lê dixe', '"Muzîka şevbêrkê" tê wateya muzîka devkî ya ku di sohbetên şevên zivistanê de tê gotin.', true),
  ('fbea4e33-70d8-4891-b948-dd84bd2e4d0d'::uuid, 'Derbarê "perwerdeya bi zimanê dayikê" de bijardeya rast kîjan e?', 'Naskirina hemwelatîbûna wekhev û mafan', 'Dayîna biryaran di nêzîktirîn yekeyên gel de', 'Mafê gelan ê perwerdeya bi zimanê xwe', 'Meclisên gel ên ku biryarên herêmî lê tên dayîn', '"Perwerdeya bi zimanê dayikê" tê wateya mafê gelan ê perwerdeya bi zimanê xwe.', true),
  ('fc1e73ab-da8f-493e-bc18-09cbad93e00b'::uuid, 'Di lêkolîna dîroka kurd û Kurdistanê de koç tê çi wateyê?', 'Herêma Kurdistana Iraqê (KRG)', 'Cihguhertina civakan', 'Serdema osmanî (sedsala 16an)', 'Împeratoriya Med (berî farsan)', 'Di lêkolîna dîroka kurd û Kurdistanê de koçberî tê wateya cihguhertina civakan.', true),
  ('fd4fc932-0431-4a5b-80c0-2ff2b3cc1887'::uuid, 'Kîjan têgeh di muzîkê de "Koma Amed" rast bi cih dike?', 'Komeke muzîkê ya alternatîf ku di salên 90î de di muzîka kurdî de şoreş çêkir', 'Hosteyê muzîkê yê bi eslê xwe ermen ku bi stranên kurdî tê nasîn', 'Cihê çandî li Wan û Amedê ku dengbêj lê tên guhdarkirin', 'Cureya muzîkê ya ku zêdetir li ser evîn û lehengiyê tê gotin', '"Koma Amed": komeke muzîkê ya alternatîf ku di salên 90î de di muzîka kurdî de şoreş çêkir.', true),
  ('fd61376d-a850-4d73-904d-342500bd28ea'::uuid, '«Newroz» ji aliyê wateya peyvê ve bi kîjan ravekirinê re nêzîk e?', 'Roja nû', 'Şeva dirêj', 'Bara kevn', 'Dengê bilind', 'Newroz bi têgeha «roja nû» re tê şirovekirin.', false),
  ('fe00799b-aab5-4bd9-be83-794b60f1029f'::uuid, 'Derbarê "hişmendiya ekolojîk" de bijardeya rast kîjan e?', 'rewşa têgihiştina ku mirov parçeyek xwezayê ye', 'pêşxistina hişmendiya civakî û ramana azad', 'civaka ku biryarên xwe dide û xwedî nirxên exlaqî ye', 'nedîtina xwezayê tenê wek tiştekî îstismarê', '"Hişmendiya ekolojîk" tê wateya rewşa têgihiştina ku mirov parçeyek xwezayê ye.', true),
  ('fe14b3bb-b5e3-44cd-ad5a-a8fb7fd91bd9'::uuid, 'Govend çi ye?', 'Muzîka takekesî', 'Şanoya dramatîk', 'Reqsa gelêrî ya bi komî', 'Pêşbirka werzişê', 'Govend reqseke gelêrî ya kurdî ye ku bi komî tê lîstin.', true),
  ('fe672060-00bd-4f6d-a30e-3069317354e4'::uuid, '"Erebê Şemo" di warê wêjeyê de çi vedibêje?', 'helbestvanê ku di serdema klasîk de berhemên kurdî nivîsîne', 'nivîskarê romana kurdî ya yekem a bi navê Şivanê Kurd', 'helbestvanê rubaiyên klasîk ê herî kevin ê wêjeya kurdî', 'nivîskar û ramangirê navdar ê berhema Mem û Zînê', '"Erebê Şemo": nivîskarê romana kurdî ya yekem a bi navê Şivanê Kurd.', true),
  ('feaf50c0-5b69-437b-bb65-09dd3d80a0ea'::uuid, 'Di sala 1845an de li Zelanda Nû rêzeşerên bi navê kîjan gelê xwecihî dest pê kirin?', 'Polînezî', 'Māori', 'Papua', 'Aborîjen', 'Şerên Zelanda Nû yên ku di 1845-an de dest pê kirin bi gelê Māori re hatine navandin.', false),
  ('ff210f70-bc74-4fe2-84bf-b57e6a25baa2'::uuid, 'Wateya gotina "sanat" bi Kurmancî çi ye?', 'ciwan', 'huner', 'reş', 'diçim', 'Peyva ''sanat'' bi Kurmancî ''huner'' e.', false),
  ('ff739c13-5262-42d0-8cda-b46cb3a004e5'::uuid, 'Di çarçoveya siyasetê de "nenavendîbûn" divê çawa bê fêmkirin?', 'mafên protesto, rêxistinbûn û azadiya derbirînê', 'vîna çareserkirina nakokiyan bi diyalogê li şûna çekan', 'destûra bingehîn a azadîxwaz a ku hemû beşên cuda dihewîne', 'belavkirina hêzê ji navendeke tekane ber bi yekeyên herêmî ve', '"Nenavendîbûn" tê wateya belavkirina hêzê ji navendeke tekane ber bi yekeyên herêmî ve.', true),
  ('ffb15863-17c6-48b1-b676-43a92ebc9825'::uuid, 'Kîjan cînavk dikare hem ji bo kesê sêyem ê yekjimar hem jî yê pirjimar were bikaranîn?', 'ew', 'ez', 'tu', 'em', 'Ew li gorî konteksê ji bo yekjimar an pirjimar tê bikaranîn.', false);
